import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ChatMessage {
  id: string;
  role: 'user' | 'model';
  text: string;
  timestamp: Date;
  isThinking?: boolean;
  groundingMetadata?: {
    search?: { url: string; title: string }[];
    maps?: { url: string; title: string }[];
  };
}

export interface InventoryItem {
  id: string;
  name: string;
  quantity: number;
  price: number;
  category: string;
}

export enum AppRoute {
  DASHBOARD = 'dashboard',
  ASSISTANT = 'assistant',
  TOOLS = 'tools',
  STRATEGY = 'strategy',
  DESIGN_DOC = 'design_doc', // The Architect's Whitepaper
}

export interface ToolConfig {
  id: string;
  name: string;
  icon: React.ReactNode;
  description: string;
  route: string;
}

export interface GeoLocation {
  lat: number;
  lng: number;
}

import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";

// Ensure API key is present
const apiKey = process.env.API_KEY || '';
if (!apiKey) {
  console.warn("Missing API_KEY in environment variables");
}

const ai = new GoogleGenAI({ apiKey });

/**
 * 1. SEARCH GROUNDING
 * Model: gemini-3-flash-preview
 * Use case: Market intelligence, regulatory updates, trends.
 */
export const searchMarketIntel = async (query: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: query,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text;
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract search URLs
    const sources = groundingChunks
      .filter((c: any) => c.web)
      .map((c: any) => ({
        url: c.web.uri,
        title: c.web.title
      }));

    return { text, sources };
  } catch (error) {
    console.error("Search Grounding Error:", error);
    throw error;
  }
};

/**
 * 2. MAPS GROUNDING
 * Model: gemini-2.5-flash
 * Use case: Finding suppliers, logistics partners.
 */
export const findLocalSuppliers = async (query: string, lat: number, lng: number) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: {
              latitude: lat,
              longitude: lng
            }
          }
        }
        // NOTE: responseMimeType is NOT allowed with googleMaps
      },
    });

    const text = response.text;
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract map links
    const places = groundingChunks
      .filter((c: any) => c.maps)
      .map((c: any) => ({
        url: c.maps.uri,
        title: c.maps.title || "Map Location"
      }));

    return { text, places };
  } catch (error) {
    console.error("Maps Grounding Error:", error);
    throw error;
  }
};

/**
 * 3. AI CHATBOT
 * Model: gemini-3-pro-preview
 * Use case: General assistance, bookkeeping help.
 */
export const chatWithAssistant = async (history: {role: string, parts: {text: string}[]}[], message: string) => {
  try {
    const chat = ai.chats.create({
      model: "gemini-3-pro-preview",
      history: history,
      config: {
        systemInstruction: "You are an expert business advisor for African informal SMEs. Speak simply, use local context where appropriate (e.g., mention Rand/Naira/Shillings if context implies), and be encouraging. Keep answers concise for mobile reading.",
      }
    });

    const result = await chat.sendMessage({ message });
    return result.text;
  } catch (error) {
    console.error("Chat Error:", error);
    throw error;
  }
};

/**
 * 4. FAST RESPONSE
 * Model: gemini-2.5-flash-lite
 * Use case: Quick calculations, translations, simple definitions.
 */
export const quickAssist = async (prompt: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite", // Correct model name for flash lite alias
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Fast Assist Error:", error);
    throw error;
  }
};

/**
 * 5. VIDEO UNDERSTANDING
 * Model: gemini-3-pro-preview
 * Use case: Analyzing inventory videos to count stock.
 */
export const analyzeInventoryVideo = async (videoFile: File, prompt: string) => {
  try {
    // Helper to convert File to Base64
    const base64Data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        // Remove data URL prefix (e.g., "data:video/mp4;base64,")
        const base64 = result.split(',')[1]; 
        resolve(base64);
      };
      reader.onerror = reject;
      reader.readAsDataURL(videoFile);
    });

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: videoFile.type,
              data: base64Data
            }
          },
          { text: prompt }
        ]
      }
    });

    return response.text;
  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

/**
 * 6. IMAGE ANALYSIS
 * Model: gemini-3-pro-preview
 * Use case: Digitizing paper receipts.
 */
export const analyzeReceiptImage = async (imageFile: File) => {
  try {
    const base64Data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        const base64 = result.split(',')[1];
        resolve(base64);
      };
      reader.onerror = reject;
      reader.readAsDataURL(imageFile);
    });

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: imageFile.type,
              data: base64Data
            }
          },
          { text: "Analyze this receipt. Extract the vendor name, total amount, date, and list of items. Format as JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            vendor: { type: Type.STRING },
            date: { type: Type.STRING },
            total: { type: Type.NUMBER },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  price: { type: Type.NUMBER }
                }
              }
            }
          }
        }
      }
    });

    return response.text;
  } catch (error) {
    console.error("Image Analysis Error:", error);
    throw error;
  }
};

/**
 * 7. THINKING MODE
 * Model: gemini-3-pro-preview with thinkingConfig
 * Use case: Complex business strategy, risk assessment, loan readiness.
 */
export const generateBusinessStrategy = async (businessContext: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Generate a detailed growth strategy for this business: ${businessContext}. Focus on risks, opportunities, and financial planning.`,
      config: {
        thinkingConfig: {
          thinkingBudget: 32768 // Max budget
        }
        // Do not set maxOutputTokens when thinkingBudget is high, unless specifically balancing
      }
    });

    return response.text;
  } catch (error) {
    console.error("Thinking Mode Error:", error);
    throw error;
  }
};

