import React, { useState, useRef, useEffect } from 'react';
import { chatWithAssistant, searchMarketIntel, findLocalSuppliers } from '../services/geminiService';
import { ChatMessage, GeoLocation } from '../types';

export const SmartAssistant: React.FC = () => {
  const [messages, setMessages] = useState<ChatMessage[]>([
    { id: '1', role: 'model', text: 'Molo! Hello! How can I help your business today?', timestamp: new Date() }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [mode, setMode] = useState<'chat' | 'search' | 'maps'>('chat');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Mock Geolocation for demo
  const [location] = useState<GeoLocation>({ lat: -26.2041, lng: 28.0473 }); // Johannesburg

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      let responseText = '';
      let groundingData = undefined;

      if (mode === 'search') {
        const result = await searchMarketIntel(userMsg.text);
        responseText = result.text;
        groundingData = { search: result.sources };
      } else if (mode === 'maps') {
        const result = await findLocalSuppliers(userMsg.text, location.lat, location.lng);
        responseText = result.text;
        groundingData = { maps: result.places };
      } else {
        // Standard Chat
        const history = messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        }));
        responseText = await chatWithAssistant(history, userMsg.text);
      }

      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
        timestamp: new Date(),
        groundingMetadata: groundingData
      };
      setMessages(prev => [...prev, botMsg]);

    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Sorry, I had trouble connecting. Please check your internet or try again.",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)]">
      {/* Mode Toggles */}
      <div className="flex space-x-2 mb-4 overflow-x-auto pb-2">
        <button 
          onClick={() => setMode('chat')}
          className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap ${mode === 'chat' ? 'bg-brand-600 text-white' : 'bg-white text-gray-600 border'}`}
        >
          General Advice
        </button>
        <button 
          onClick={() => setMode('search')}
          className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap flex items-center ${mode === 'search' ? 'bg-blue-600 text-white' : 'bg-white text-gray-600 border'}`}
        >
          <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" /></svg>
          Market Search
        </button>
        <button 
          onClick={() => setMode('maps')}
          className={`px-4 py-2 rounded-full text-sm font-medium whitespace-nowrap flex items-center ${mode === 'maps' ? 'bg-green-600 text-white' : 'bg-white text-gray-600 border'}`}
        >
          <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M5.05 4.05a7 7 0 119.9 9.9L10 18.9l-4.95-4.95a7 7 0 010-9.9zM10 11a2 2 0 100-4 2 2 0 000 4z" clipRule="evenodd" /></svg>
          Find Suppliers
        </button>
      </div>

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto space-y-4 p-2" ref={scrollRef}>
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 ${msg.role === 'user' ? 'bg-brand-600 text-white' : 'bg-white border border-gray-200 text-gray-800'}`}>
              <div className="whitespace-pre-wrap">{msg.text}</div>

              {/* Grounding Sources */}
              {msg.groundingMetadata?.search && (
                <div className="mt-3 pt-3 border-t border-gray-100">
                  <p className="text-xs font-bold text-gray-500 mb-1">Sources:</p>
                  <ul className="space-y-1">
                    {msg.groundingMetadata.search.map((s, idx) => (
                      <li key={idx}>
                        <a href={s.url} target="_blank" rel="noreferrer" className="text-xs text-blue-500 hover:underline truncate block">
                          {s.title}
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
               {msg.groundingMetadata?.maps && (
                <div className="mt-3 pt-3 border-t border-gray-100">
                  <p className="text-xs font-bold text-gray-500 mb-1">Locations Found:</p>
                  <ul className="space-y-1">
                    {msg.groundingMetadata.maps.map((s, idx) => (
                      <li key={idx}>
                        <a href={s.url} target="_blank" rel="noreferrer" className="text-xs text-green-600 hover:underline truncate flex items-center">
                           <span className="mr-1">📍</span> {s.title}
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-gray-200 rounded-2xl p-4 flex items-center space-x-2">
              <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
              <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
              <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <div className="pt-4 mt-2 border-t border-gray-100 bg-gray-50 sticky bottom-0">
        <div className="flex items-center space-x-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder={
              mode === 'search' ? "Ask about market prices..." :
              mode === 'maps' ? "Find wholesalers near me..." :
              "Ask me anything..."
            }
            className="flex-1 border-gray-300 rounded-full px-4 py-3 shadow-sm focus:ring-2 focus:ring-brand-500 focus:border-transparent"
          />
          <button
            onClick={handleSend}
            disabled={isLoading || !input.trim()}
            className="bg-brand-600 text-white p-3 rounded-full shadow-md disabled:opacity-50"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </button>
        </div>
        <div className="text-center mt-2">
          <span className="text-xs text-gray-400">Voice Input Supported (Tap Mic)</span>
        </div>
      </div>
    </div>
  );
};

