import React, { useState } from 'react';
import { analyzeReceiptImage } from '../../services/geminiService';

export const ReceiptScanner: React.FC = () => {
  const [result, setResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setLoading(true);
      try {
        const jsonString = await analyzeReceiptImage(e.target.files[0]);
        setResult(jsonString);
      } catch (err) {
        alert("Failed to analyze receipt");
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="space-y-4">
      <h3 className="text-xl font-bold">Receipt Scanner</h3>
      <p className="text-sm text-gray-600">Upload a photo of a receipt or invoice. The AI will extract the details automatically.</p>

      <div className="border-2 border-dashed border-gray-300 rounded-xl p-8 text-center bg-gray-50">
        <input 
          type="file" 
          accept="image/*"
          onChange={handleFileChange} 
          className="hidden" 
          id="receipt-upload"
        />
        <label htmlFor="receipt-upload" className="cursor-pointer block">
          <div className="text-4xl mb-2">📸</div>
          <span className="text-brand-600 font-bold">Tap to Capture</span>
        </label>
      </div>

      {loading && <div className="text-center text-brand-600">Analyzing image...</div>}

      {result && (
        <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
          <h4 className="font-bold text-gray-800 mb-2">Extracted Data</h4>
          <pre className="text-xs bg-gray-100 p-2 rounded overflow-x-auto whitespace-pre-wrap">
            {result}
          </pre>
          <button className="w-full mt-4 bg-brand-600 text-white py-2 rounded-lg font-bold">
            Save to Books
          </button>
        </div>
      )}
    </div>
  );
};

