/**
 * 5. VIDEO UNDERSTANDING
 * Model: gemini-3-pro-preview
 * Use case: Analyzing inventory videos to count stock.
 */
export const analyzeInventoryVideo = async (videoFile: File, prompt: string) => {
  try {
    // Helper to convert File to Base64
    const base64Data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        // Remove data URL prefix (e.g., "data:video/mp4;base64,")
        const base64 = result.split(',')[1]; 
        resolve(base64);
      };
      reader.onerror = reject;
      reader.readAsDataURL(videoFile);
    });

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: videoFile.type,
              data: base64Data
            }
          },
          { text: prompt }
        ]
      }
    });

    return response.text;
  } catch (error) {
    console.error("Video Analysis Error:", error);
    throw error;
  }
};

/**
 * 6. IMAGE ANALYSIS
 * Model: gemini-3-pro-preview
 * Use case: Digitizing paper receipts.
 */
export const analyzeReceiptImage = async (imageFile: File) => {
  try {
    const base64Data = await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const result = reader.result as string;
        const base64 = result.split(',')[1];
        resolve(base64);
      };
      reader.onerror = reject;
      reader.readAsDataURL(imageFile);
    });

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: imageFile.type,
              data: base64Data
            }
          },
          { text: "Analyze this receipt. Extract the vendor name, total amount, date, and list of items. Format as JSON." }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            vendor: { type: Type.STRING },
            date: { type: Type.STRING },
            total: { type: Type.NUMBER },
            items: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  price: { type: Type.NUMBER }
                }
              }
            }
          }
        }
      }
    });

    return response.text;
  } catch (error) {
    console.error("Image Analysis Error:", error);
    throw error;
  }
};

