import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './pages/Dashboard';
import { SmartAssistant } from './pages/SmartAssistant';
import { Tools } from './pages/Tools';
import { SystemDesign } from './pages/SystemDesign';
import { Sales } from './pages/Sales';
import { Trade } from './pages/Trade';
import { Finance } from './pages/Finance';
import { Compliance } from './pages/Compliance';
import { AppRoute } from './types';
import { ReceiptScanner } from './pages/Tools/ReceiptScanner';
import { InventoryVideo } from './pages/Tools/InventoryVideo';
import { BusinessStrategy } from './pages/Tools/BusinessStrategy';

const App: React.FC = () => {
  const [route, setRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [activeTool, setActiveTool] = useState<string | null>(null);

  const renderContent = () => {
    // Legacy Tool Routing Logic
    if (activeTool) {
      return (
        <div className="space-y-4">
           <button 
             onClick={() => setActiveTool(null)} 
             className="flex items-center text-sm text-gray-500 hover:text-gray-800"
           >
             <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             Back to Tools
           </button>
           {activeTool === 'receipt_scanner' && <ReceiptScanner />}
           {activeTool === 'inventory_video' && <InventoryVideo />}
           {activeTool === 'business_strategy' && <BusinessStrategy />}
           {activeTool === 'quick_calc' && <div className="p-4 bg-yellow-50 rounded text-center text-yellow-800">Use the Smart Assistant for Quick Calculations!</div>}
        </div>
      );
    }

    // Main Route Switch
    switch (route) {
      case AppRoute.DASHBOARD:
        return <Dashboard onNavigate={setRoute} />;
      case AppRoute.SALES:
        return <Sales />;
      case AppRoute.TRADE:
        return <Trade />;
      case AppRoute.FINANCE:
        return <Finance />;
      case AppRoute.COMPLIANCE:
        return <Compliance />;
      case AppRoute.ASSISTANT:
        return <SmartAssistant />;
      case AppRoute.TOOLS:
        return <Tools onSelectTool={setActiveTool} />;
      case AppRoute.DESIGN_DOC:
        return <SystemDesign />;
      default:
        return <Dashboard onNavigate={setRoute} />;
    }
  };

  const handleNavigate = (newRoute: AppRoute) => {
    setActiveTool(null);
    setRoute(newRoute);
  };

  return (
    <Layout currentRoute={route} onNavigate={handleNavigate}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import { GoogleGenAI, Type, FunctionDeclaration } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * 1. SEARCH GROUNDING
 * Model: gemini-3-flash-preview
 * Use case: Market intelligence, regulatory updates, trends.
 */
export const searchMarketIntel = async (query: string) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: query,
      config: {
        tools: [{ googleSearch: {} }],
      },
    });

    const text = response.text;
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract search URLs
    const sources = groundingChunks
      .filter((c: any) => c.web)
      .map((c: any) => ({
        url: c.web.uri,
        title: c.web.title
      }));

    return { text, sources };
  } catch (error) {
    console.error("Search Grounding Error:", error);
    throw error;
  }
};

/**
 * 2. MAPS GROUNDING
 * Model: gemini-2.5-flash
 * Use case: Finding suppliers, logistics partners.
 */
export const findLocalSuppliers = async (query: string, lat: number, lng: number) => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: query,
      config: {
        tools: [{ googleMaps: {} }],
        toolConfig: {
          retrievalConfig: {
            latLng: {
              latitude: lat,
              longitude: lng
            }
          }
        }
        // NOTE: responseMimeType is NOT allowed with googleMaps
      },
    });

    const text = response.text;
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    // Extract map links
    const places = groundingChunks
      .filter((c: any) => c.maps)
      .map((c: any) => ({
        url: c.maps.uri,
        title: c.maps.title || "Map Location"
      }));

    return { text, places };
  } catch (error) {
    console.error("Maps Grounding Error:", error);
    throw error;
  }
};

/**
 * 3. AI CHATBOT
 * Model: gemini-3-pro-preview
 * Use case: General assistance, bookkeeping help.
 */
export const chatWithAssistant = async (history: {role: string, parts: {text: string}[]}[], message: string) => {
  try {
    const chat = ai.chats.create({
      model: "gemini-3-pro-preview",
      history: history,
      config: {
        systemInstruction: `You are the IBOS Intelligent Agent. You are not just a chatbot; you are a proactive business partner for African SMEs. 

