          <svg className="w-3 h-3 mr-1" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z" clipRule="evenodd" /></svg>
          Market Intel
        </button>
        <button 
          onClick={() => setMode('maps')}
          className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap uppercase tracking-wider flex items-center ${mode === 'maps' ? 'bg-green-600 text-white' : 'bg-white text-gray-500 border border-gray-200'}`}
