          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] rounded-2xl p-4 shadow-sm ${msg.role === 'user' ? 'bg-brand-600 text-white' : 'bg-white border border-gray-200 text-gray-800'}`}>
              <div className="whitespace-pre-wrap text-sm leading-relaxed">{msg.text}</div>

              {/* Grounding Sources */}
              {msg.groundingMetadata?.search && (
                <div className="mt-3 pt-3 border-t border-gray-100/20">
                  <p className="text-[10px] font-bold opacity-70 mb-1">SOURCES:</p>
                  <ul className="space-y-1">
                    {msg.groundingMetadata.search.map((s, idx) => (
                      <li key={idx}>
                        <a href={s.url} target="_blank" rel="noreferrer" className="text-xs text-blue-400 hover:text-blue-200 hover:underline truncate block">
                          {s.title}
                        </a>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
               {msg.groundingMetadata?.maps && (
                <div className="mt-3 pt-3 border-t border-gray-100/20">
                  <p className="text-[10px] font-bold opacity-70 mb-1">LOCATIONS FOUND:</p>
                  <ul className="space-y-1">
                    {msg.groundingMetadata.maps.map((s, idx) => (
                      <li key={idx}>
                        <a href={s.url} target="_blank" rel="noreferrer" className="text-xs text-green-500 hover:underline truncate flex items-center">
                           <span className="mr-1">📍</span> {s.title}
                        </a>
                      </li>
                    ))}
