// --- GAUGE METER ---
export const Gauge: React.FC<{ value: number; max?: number; label: string; subtext?: string; color?: string }> = ({ 
  value, max = 100, label, subtext, color = 'border-brand-500' 
}) => {
  // Simplified visual representation for the gauge using CSS rotation
  const percentage = (value / max) * 100;
  const rotation = (percentage / 100) * 180; // 180 degree semi-circle

  return (
    <div className="relative text-center">
      <div className="relative w-40 h-20 mx-auto overflow-hidden">
        {/* Background Arc */}
        <div className="absolute top-0 left-0 w-40 h-40 rounded-full border-[12px] border-gray-100 box-border"></div>
        {/* Foreground Arc (Masked) */}
        {/* Note: A true CSS arc requires simpler transforms for reliability across browsers. Using a clipped box method. */}
        <div 
           className={`absolute top-0 left-0 w-40 h-40 rounded-full border-[12px] ${color} border-b-transparent border-l-transparent transform transition-transform duration-1000 ease-out`}
           style={{ transform: `rotate(${rotation - 45 - 180}deg)` }} // Adjust logic for CSS arc
        ></div>
        {/* Re-implementing simplified style for robustness */}
        <div className="absolute top-0 left-0 w-40 h-40 rounded-full border-[12px] border-gray-100 border-b-transparent border-r-transparent transform rotate-45"></div>
         <div 
           className={`absolute top-0 left-0 w-40 h-40 rounded-full border-[12px] ${color} border-b-transparent border-r-transparent transform transition-transform duration-1000 ease-out origin-center`}
           style={{ transform: `rotate(${rotation - 135}deg)` }}
        ></div>

        <div className="absolute bottom-0 w-full text-center">
           <span className="text-3xl font-extrabold text-gray-900">{value}</span>
        </div>
      </div>
      <p className="text-xs font-bold text-gray-400 uppercase tracking-wider mt-2">{label}</p>
      {subtext && <p className="text-[10px] text-gray-500 mt-1">{subtext}</p>}
    </div>
  );
};

