import React, { useState, useRef, useEffect } from 'react';
import { chatWithAssistant, searchMarketIntel, findLocalSuppliers } from '../services/geminiService';
import { ChatMessage, GeoLocation } from '../types';
import { AIChatBubble, Input, Button } from '../components/DesignSystem';

export const SmartAssistant: React.FC = () => {
  // Script A: Onboarding Script (Initial Greeting)
  const [messages, setMessages] = useState<ChatMessage[]>([
    { 
      id: '1', 
      role: 'model', 
      text: 'Welcome. You don’t need paperwork to start.\nJust record today’s sale — I’ll handle the rest.', 
      timestamp: new Date() 
    }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [mode, setMode] = useState<'chat' | 'search' | 'maps'>('chat');
  const scrollRef = useRef<HTMLDivElement>(null);

  // Mock Geolocation for demo
  const [location] = useState<GeoLocation>({ lat: -26.2041, lng: 28.0473 }); // Johannesburg

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  // Contextual Insights (Scripts B, C, D, E)
  const insights = [
    {
      id: 'sales',
      type: 'Opportunity',
      icon: '📈',
      title: 'Sales Insight',
      text: 'You made more on Fridays. If you stock 10 more units, your income could grow by 18%.',
      color: 'bg-primary-50 border-primary-100 text-primary-800'
    },
    {
      id: 'compliance',
      type: 'Compliance',
      icon: '🌍',
      title: 'Export Ready',
      text: 'You are 60% ready to export to Botswana. I can help you complete the missing steps.',
      color: 'bg-blue-50 border-blue-100 text-blue-800'
    },
    {
      id: 'risk',
      type: 'Alert',
      icon: '⚠️',
      title: 'Risk Alert',
      text: 'Your expenses increased faster than income this week. Let’s review what changed.',
      color: 'bg-orange-50 border-orange-100 text-orange-800'
    }
  ];

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if (!textToSend.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);

    try {
      let responseText = '';
      let groundingData = undefined;

      if (mode === 'search') {
        const result = await searchMarketIntel(userMsg.text);
        responseText = result.text;
        groundingData = { search: result.sources };
      } else if (mode === 'maps') {
        const result = await findLocalSuppliers(userMsg.text, location.lat, location.lng);
        responseText = result.text;
        groundingData = { maps: result.places };
      } else {
        // Standard Chat
        const history = messages.map(m => ({
          role: m.role,
          parts: [{ text: m.text }]
        }));
        responseText = await chatWithAssistant(history, userMsg.text);
      }

      const botMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        text: responseText,
        timestamp: new Date(),
        groundingMetadata: groundingData
      };
      setMessages(prev => [...prev, botMsg]);

    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        text: "Sorry, I had trouble connecting. Please check your internet or try again.",
        timestamp: new Date()
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex flex-col h-[calc(100vh-140px)]">
      {/* Mode Toggles */}
      <div className="flex space-x-2 mb-2 overflow-x-auto pb-2 px-1">
        <button 
          onClick={() => setMode('chat')}
          className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap uppercase tracking-wider ${mode === 'chat' ? 'bg-primary-600 text-white' : 'bg-white text-neutral-500 border border-neutral-200'}`}
        >
          Assistant
        </button>
        <button 
          onClick={() => setMode('search')}
          className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap uppercase tracking-wider flex items-center ${mode === 'search' ? 'bg-blue-600 text-white' : 'bg-white text-neutral-500 border border-neutral-200'}`}
        >
          Market Intel
        </button>
        <button 
          onClick={() => setMode('maps')}
          className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap uppercase tracking-wider flex items-center ${mode === 'maps' ? 'bg-green-600 text-white' : 'bg-white text-neutral-500 border border-neutral-200'}`}
        >
          Suppliers
        </button>
      </div>

      {/* Proactive Context Engine (Insights) */}
      {messages.length < 3 && (
        <div className="mb-4">
          <div className="flex space-x-3 overflow-x-auto pb-4 pt-2 px-1 scrollbar-hide">
            {insights.map((insight) => (
              <button
                key={insight.id}
                onClick={() => handleSend(`Tell me more about this: "${insight.text}"`)}
                className={`flex-shrink-0 w-64 p-4 rounded-2xl border text-left transition-transform hover:scale-105 active:scale-95 shadow-sm ${insight.color}`}
              >
                <div className="flex justify-between items-start mb-2">
                  <span className="text-[10px] font-black uppercase tracking-widest opacity-70">{insight.type}</span>
                  <span className="text-xl">{insight.icon}</span>
                </div>
                <h4 className="font-bold text-sm mb-1">{insight.title}</h4>
                <p className="text-xs opacity-90 leading-relaxed">{insight.text}</p>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Chat Area */}
      <div className="flex-1 overflow-y-auto space-y-4 p-2 pl-10" ref={scrollRef}>
        {messages.map((msg) => (
          <AIChatBubble 
            key={msg.id}
            message={msg.text}
            isUser={msg.role === 'user'}
            timestamp={msg.timestamp}
            grounding={msg.groundingMetadata}
          />
        ))}
        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-white border border-neutral-200 rounded-2xl p-4 flex items-center space-x-2">
              <div className="w-2 h-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
              <div className="w-2 h-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
              <div className="w-2 h-2 bg-neutral-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
            </div>
          </div>
        )}
      </div>

      {/* Input Area */}
      <div className="pt-4 mt-2 border-t border-neutral-100 bg-neutral-50 sticky bottom-0">
        <div className="flex items-center space-x-2">
          <div className="flex-1">
            <Input 
                variant="voice"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Just tell me: 'I sold bread for 200 rand'..."
            />
          </div>
          <Button 
            onClick={() => handleSend()}
            disabled={isLoading || !input.trim()}
            variant="primary"
            className="p-3 rounded-xl shadow-md"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
          </Button>
        </div>
        <div className="text-center mt-2 pb-2">
          <span className="text-[10px] font-bold text-neutral-400 uppercase tracking-widest">Voice Recording Supported</span>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
