                    <span className="text-2xl text-gray-400 mt-1 mr-1">{currency === 'ZAR' ? 'R' : '₦'}</span>
                    {amount || '0'}
                </div>

                {/* Converted Display */}
                {amount && amount !== '0' && (
                    <div className="mt-4 pt-4 border-t border-neutral-100 animate-fade-in">
