            <div className="space-y-3">
                {[
                    { id: 'sales', label: 'Track daily sales', icon: '💰' },
                    { id: 'expenses', label: 'Control expenses', icon: '📉' },
                    { id: 'funding', label: 'Access funding', icon: '🏦' },
                    { id: 'compliance', label: 'Become compliant', icon: '📜' },
