        <Button variant="ghost" fullWidth onClick={onComplete}>
            Continue as Guest (7 Days)
        </Button>
    </div>
  );

  return (
    <div className="min-h-screen bg-neutral-50 flex flex-col">
       {/* Progress Bar (Hidden on Step 1) */}
       {step > 1 && (
         <div className="w-full h-1 bg-neutral-200">
            <div className="h-full bg-brand-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
         </div>
       )}

       <div className="flex-1 flex flex-col justify-center p-6 max-w-md mx-auto w-full">
         {step > 1 && (
            <button onClick={() => setStep(step - 1)} className="self-start text-neutral-400 mb-4 hover:text-neutral-600">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </button>
         )}

         {step === 1 && renderStep1()}
         {step === 2 && renderStep2()}
         {step === 3 && renderStep3()}
         {step === 4 && renderStep4()}
         {step === 5 && renderStep5()}
       </div>
    </div>
  );
