import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './pages/Dashboard';
import { SmartAssistant } from './pages/SmartAssistant';
import { Tools } from './pages/Tools';
import { SystemDesign } from './pages/SystemDesign';
import { Sales } from './pages/Sales';
import { Trade } from './pages/Trade';
import { Finance } from './pages/Finance';
import { Compliance } from './pages/Compliance';
import { AppRoute } from './types';
import { ReceiptScanner } from './pages/Tools/ReceiptScanner';
import { InventoryVideo } from './pages/Tools/InventoryVideo';
import { BusinessStrategy } from './pages/Tools/BusinessStrategy';
import { Login } from './pages/Auth/Login';
import { Onboarding } from './pages/Auth/Onboarding';

const App: React.FC = () => {
  // Auth State: 'ONBOARDING' is default for demo to show the flow
  const [authView, setAuthView] = useState<'LOGIN' | 'ONBOARDING' | 'APP'>('ONBOARDING');

  const [route, setRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [activeTool, setActiveTool] = useState<string | null>(null);

  const handleAuthComplete = () => {
    setAuthView('APP');
  };

  if (authView === 'LOGIN') {
    return <Login onLogin={handleAuthComplete} onGoToSignup={() => setAuthView('ONBOARDING')} />;
  }

  if (authView === 'ONBOARDING') {
    return <Onboarding onComplete={handleAuthComplete} onLogin={() => setAuthView('LOGIN')} />;
  }

  const renderContent = () => {
    // Legacy Tool Routing Logic
    if (activeTool) {
      return (
        <div className="space-y-4">
           <button 
             onClick={() => setActiveTool(null)} 
             className="flex items-center text-sm text-gray-500 hover:text-gray-800"
           >
             <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             Back to Tools
           </button>
           {activeTool === 'receipt_scanner' && <ReceiptScanner />}
           {activeTool === 'inventory_video' && <InventoryVideo />}
           {activeTool === 'business_strategy' && <BusinessStrategy />}
           {activeTool === 'quick_calc' && <div className="p-4 bg-yellow-50 rounded text-center text-yellow-800">Use the Smart Assistant for Quick Calculations!</div>}
        </div>
      );
    }

    // Main Route Switch
    switch (route) {
      case AppRoute.DASHBOARD:
        return <Dashboard onNavigate={setRoute} />;
      case AppRoute.SALES:
        return <Sales />;
      case AppRoute.TRADE:
        return <Trade />;
      case AppRoute.FINANCE:
        return <Finance />;
      case AppRoute.COMPLIANCE:
        return <Compliance />;
      case AppRoute.ASSISTANT:
        return <SmartAssistant />;
      case AppRoute.TOOLS:
        return <Tools onSelectTool={setActiveTool} />;
      case AppRoute.DESIGN_DOC:
        return <SystemDesign />;
      default:
        return <Dashboard onNavigate={setRoute} />;
    }
  };

  const handleNavigate = (newRoute: AppRoute) => {
    setActiveTool(null);
    setRoute(newRoute);
  };

  return (
    <Layout currentRoute={route} onNavigate={handleNavigate}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { Card, Button, Badge, Modal } from '../components/DesignSystem';

export const Sales: React.FC = () => {
    const [amount, setAmount] = useState('');
    const [currency, setCurrency] = useState<'ZAR' | 'NGN'>('ZAR');

    // QR Code & Transaction State
    const [showQR, setShowQR] = useState(false);
    const [showInvoice, setShowInvoice] = useState(false);
    const [lastTx, setLastTx] = useState<{id: string, amount: string, curr: string} | null>(null);

    // List of recent transactions
    const [transactions, setTransactions] = useState([
        { id: '1', item: "Metal Welding (Gate)", time: "10:30 AM", amount: "1500", curr: 'ZAR' },
        { id: '2', item: "Repair Service", time: "09:15 AM", amount: "32000", curr: 'NGN' },
        { id: '3', item: "Vegetable Box", time: "Yesterday", amount: "120", curr: 'ZAR' },
    ]);

    // Mock Exchange Rate: 1 ZAR = 92.50 NGN
    const EXCHANGE_RATE = 92.50;

    const handleNum = (num: string) => {
        if (num === 'C') {
            setAmount('');
        } else if (num === 'back') {
            setAmount(prev => prev.slice(0, -1));
        } else {
            if (num === '.' && amount.includes('.')) return;
            // Prevent too many decimals
            if (amount.includes('.') && amount.split('.')[1].length >= 2) return;
            setAmount(prev => prev + num);
        }
    };

    const toggleCurrency = () => {
        setCurrency(prev => prev === 'ZAR' ? 'NGN' : 'ZAR');
    };

    const getConvertedAmount = () => {
        const val = parseFloat(amount || '0');
        if (currency === 'ZAR') {
            // ZAR to NGN
            return (val * EXCHANGE_RATE).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        } else {
            // NGN to ZAR
            return (val / EXCHANGE_RATE).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
        }
    };

    const handleRecord = () => {
        if (!amount || parseFloat(amount) === 0) return;

        const newTx = {
            id: Date.now().toString(),
            amount: amount,
            curr: currency,
            item: "General Sale", // Default description
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setLastTx({ id: newTx.id, amount: newTx.amount, curr: newTx.curr });
        setTransactions(prev => [newTx, ...prev].slice(0, 5)); // Add to top, keep last 5
        setShowQR(true);
    };

    const handleInvoice = () => {
        if (!amount || parseFloat(amount) === 0) return;

        const newTx = {
            id: Date.now().toString(),
            amount: amount,
            curr: currency,
            item: "Invoice Generated",
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        setLastTx({ id: newTx.id, amount: newTx.amount, curr: newTx.curr });
        // Optional: Add invoices to transaction list too? The prompt says "recorded transactions", usually invoices become transactions when paid, but for simplicity let's assume tracking generated invoices is useful or just leave it as is.
        // I will focus on handleRecord for adding to the list as that implies a completed sale usually in this context.
        // However, user might want to see the invoice they just made.
        // Let's stick to handleRecord adding to the list as it is "Sales" page.

        setShowInvoice(true);
    };

    const handleShareWhatsApp = () => {
        if (!lastTx) return;
        const date = new Date().toLocaleString();
        const symbol = lastTx.curr === 'ZAR' ? 'R' : '₦';
        const message = `🧾 *INVOICE*\n\n*Ref:* ${lastTx.id.slice(-6)}\n*Date:* ${date}\n*Amount:* ${symbol} ${lastTx.amount}\n\n*Status:* Pending Payment\n\n_Generated by IBOS_`;

        const url = `https://wa.me/?text=${encodeURIComponent(message)}`;
        window.open(url, '_blank');
        setShowInvoice(false);
    };

    const handleCloseQR = () => {
        setShowQR(false);
        setAmount('');
        setLastTx(null);
    };

    const targetCurrency = currency === 'ZAR' ? 'NGN' : 'ZAR';
    const convertedValue = getConvertedAmount();

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold text-gray-900">New Sale</h2>
                <div className="flex space-x-2">
                    <Button variant="ghost" size="sm" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>} />
                    <Button variant="ghost" size="sm" icon={<svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" /></svg>} />
                </div>
            </div>

            {/* Display */}
