            <span className="text-xs font-bold text-neutral-300">XH</span>
        </div>
      </div>
    </div>
  );

  // STEP 2: BUSINESS IDENTITY
  const renderStep2 = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="text-center mb-8">
         <h2 className="text-2xl font-bold text-neutral-900">Tell us about your business</h2>
         <p className="text-neutral-500 text-sm mt-2">No documents needed.</p>
       </div>

       <Input 
         label="Business Name (Optional)"
         placeholder="e.g. Mama Dlamini Veg"
         value={formData.businessName}
         onChange={(e) => setFormData({...formData, businessName: e.target.value})}
       />

       <div className="space-y-2">
         <label className="block text-xs font-bold text-neutral-500 ml-1">Business Type</label>
         <div className="grid grid-cols-2 gap-3">
            {[
                { id: 'trading', label: 'Trading', icon: '🏪' },
                { id: 'services', label: 'Services', icon: '🔧' },
                { id: 'manufacturing', label: 'Making', icon: '🔨' },
                { id: 'farming', label: 'Farming', icon: '🌽' },
            ].map((type) => (
                <button
                    key={type.id}
                    onClick={() => setFormData({...formData, businessType: type.id})}
                    className={`p-4 rounded-xl border-2 text-left transition-all ${
                        formData.businessType === type.id 
                        ? 'border-brand-500 bg-brand-50 ring-1 ring-brand-500' 
                        : 'border-neutral-100 bg-white hover:border-neutral-200'
                    }`}
                >
                    <div className="text-2xl mb-2">{type.icon}</div>
                    <div className="font-bold text-sm text-neutral-900">{type.label}</div>
                </button>
            ))}
         </div>
       </div>

       <Button fullWidth size="lg" onClick={nextStep} disabled={!formData.businessType}>
         Next
       </Button>
    </div>
  );

  // STEP 3: INTENT
  const renderStep3 = () => {
      const toggleIntent = (id: string) => {
          const current = formData.intents;
          if (current.includes(id)) {
              setFormData({...formData, intents: current.filter(i => i !== id)});
          } else {
              setFormData({...formData, intents: [...current, id]});
          }
      };

      return (
        <div className="space-y-6 animate-fade-in">
            <div className="text-center mb-8">
                <h2 className="text-2xl font-bold text-neutral-900">What do you want help with?</h2>
                <p className="text-neutral-500 text-sm mt-2">Select all that apply</p>
            </div>

            <div className="space-y-3">
                {[
                    { id: 'sales', label: 'Track daily sales', icon: '💰' },
                    { id: 'expenses', label: 'Control expenses', icon: '📉' },
                    { id: 'funding', label: 'Access funding', icon: '🏦' },
                    { id: 'compliance', label: 'Become compliant', icon: '📜' },
                ].map((item) => (
                    <button
                        key={item.id}
                        onClick={() => toggleIntent(item.id)}
                        className={`w-full p-4 rounded-xl border flex items-center transition-all ${
                            formData.intents.includes(item.id)
                            ? 'border-brand-500 bg-brand-50 shadow-sm'
                            : 'border-neutral-100 bg-white'
                        }`}
                    >
                        <div className={`w-6 h-6 rounded-full border flex items-center justify-center mr-4 ${
                            formData.intents.includes(item.id) ? 'bg-brand-500 border-brand-500 text-white' : 'border-neutral-300'
                        }`}>
                            {formData.intents.includes(item.id) && <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" /></svg>}
                        </div>
                        <span className="text-xl mr-3">{item.icon}</span>
                        <span className="font-bold text-neutral-900">{item.label}</span>
                    </button>
                ))}
            </div>

            <Button fullWidth size="lg" onClick={nextStep} disabled={formData.intents.length === 0}>
                Next
            </Button>
        </div>
      );
  };

  // STEP 4: FIRST SALE (VALUE MOMENT)
  const renderStep4 = () => (
    <div className="space-y-6 animate-fade-in text-center">
        <div className="mb-8">
            <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-2xl">💵</span>
            </div>
            <h2 className="text-2xl font-bold text-neutral-900">Let’s record your first sale</h2>
            <p className="text-neutral-500 text-sm mt-2">See how easy it is.</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-neutral-200">
             <label className="block text-xs font-bold text-neutral-400 uppercase tracking-wider mb-2">Amount (ZAR)</label>
             <input 
                type="number" 
                className="text-4xl font-extrabold text-neutral-900 text-center w-full focus:outline-none placeholder-neutral-200"
                placeholder="0"
                autoFocus
                value={formData.firstSaleAmount}
                onChange={(e) => setFormData({...formData, firstSaleAmount: e.target.value})}
             />
        </div>

        <div className="flex space-x-3 pt-4">
             <Button fullWidth variant="ghost" onClick={nextStep}>Skip</Button>
             <Button fullWidth size="lg" onClick={nextStep} disabled={!formData.firstSaleAmount}>Record Sale</Button>
        </div>
    </div>
  );

  // STEP 5: SIGN UP / AUTH
  const renderStep5 = () => (
    <div className="space-y-6 animate-fade-in">
        <div className="text-center mb-6">
            <h2 className="text-2xl font-bold text-neutral-900">Create your account</h2>
            <p className="text-neutral-500 text-sm mt-2">Secure your business data.</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-neutral-100 space-y-4">
             <Input 
                label="Full Name"
                placeholder="e.g. Thabo Mbeki"
                value={formData.fullName}
                onChange={(e) => setFormData({...formData, fullName: e.target.value})}
             />

             <Input 
                label="Business Name"
                placeholder="e.g. Mama Dlamini Veg"
                value={formData.businessName}
                onChange={(e) => setFormData({...formData, businessName: e.target.value})}
             />

             <Input 
                label="Email Address"
                type="email"
                placeholder="e.g. name@example.com"
                value={formData.email}
                onChange={(e) => setFormData({...formData, email: e.target.value})}
             />

             <div>
                <label className="block text-xs font-bold text-neutral-500 mb-1 ml-1">Phone Number</label>
                <div className="flex space-x-2">
                    <select 
                        className="w-24 border-neutral-300 rounded-xl px-2 py-3 shadow-sm focus:ring-2 focus:ring-primary-500 focus:border-transparent text-neutral-900 bg-white"
                        value={formData.countryCode}
                        onChange={(e) => setFormData({...formData, countryCode: e.target.value})}
                    >
                        <option value="+27">🇿🇦 +27</option>
                        <option value="+234">🇳🇬 +234</option>
                        <option value="+254">🇰🇪 +254</option>
                        <option value="+233">🇬🇭 +233</option>
                    </select>
                    <input 
                        className="flex-1 border-neutral-300 rounded-xl px-4 py-3 shadow-sm focus:ring-2 focus:ring-primary-500 focus:border-transparent text-neutral-900 placeholder-neutral-400"
                        placeholder="e.g. 72 123 4567"
                        value={formData.phone}
                        onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    />
                </div>
             </div>

             <div className="text-xs text-neutral-400 text-center pt-2">
                By continuing, you agree to our Terms of Service.
             </div>

             <Button fullWidth size="lg" onClick={onComplete} disabled={!formData.phone || !formData.fullName} className="shadow-lg shadow-brand-500/30">
                Complete Setup
             </Button>
        </div>

        <Button variant="ghost" fullWidth onClick={onComplete}>
            Continue as Guest (7 Days)
        </Button>
    </div>
  );

  return (
    <div className="min-h-screen bg-neutral-50 flex flex-col">
       {/* Progress Bar (Hidden on Step 1) */}
       {step > 1 && (
         <div className="w-full h-1 bg-neutral-200">
            <div className="h-full bg-brand-500 transition-all duration-500" style={{ width: `${progress}%` }}></div>
         </div>
       )}

       <div className="flex-1 flex flex-col justify-center p-6 max-w-md mx-auto w-full">
         {step > 1 && (
            <button onClick={() => setStep(step - 1)} className="self-start text-neutral-400 mb-4 hover:text-neutral-600">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </button>
         )}

         {step === 1 && renderStep1()}
         {step === 2 && renderStep2()}
         {step === 3 && renderStep3()}
         {step === 4 && renderStep4()}
         {step === 5 && renderStep5()}
       </div>
    </div>
  );
};

