import React, { useState } from 'react';
import { Card, Button, Badge, Modal, Toast } from '../components/DesignSystem';

export const Sales: React.FC = () => {
    // POS State
    const [viewMode, setViewMode] = useState<'keypad' | 'grid'>('grid'); // Default to grid for speed
    const [amount, setAmount] = useState('0');
    const [currency, setCurrency] = useState<'ZAR' | 'NGN'>('ZAR');

    // Transaction State
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [showReceiptModal, setShowReceiptModal] = useState(false);
    const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'mobile' | null>(null);
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });

    // Mock Favorites Data
    const quickItems = [
        { id: '1', name: 'Bread', price: 18, icon: '🍞' },
        { id: '2', name: 'Milk', price: 22, icon: '🥛' },
        { id: '3', name: 'Coke', price: 15, icon: '🥤' },
        { id: '4', name: 'Airtime', price: 10, icon: '📱' },
        { id: '5', name: 'Chips', price: 12, icon: '🥔' },
        { id: '6', name: 'Meal', price: 45, icon: '🍲' },
    ];

    // Transaction History
    const [transactions, setTransactions] = useState([
        { id: '1', item: "Bread, Milk", time: "10:30", amount: "40", method: 'cash' },
        { id: '2', item: "Airtime", time: "09:15", amount: "10", method: 'mobile' },
    ]);

    // --- LOGIC ---

    const addToTotal = (price: number) => {
        setAmount((prev) => (parseFloat(prev) + price).toString());
    };

    const handleNum = (num: string) => {
        if (num === 'C') {
            setAmount('0');
        } else if (num === 'back') {
            setAmount(prev => prev.length > 1 ? prev.slice(0, -1) : '0');
        } else {
            setAmount(prev => prev === '0' ? num : prev + num);
        }
    };

    const initiatePayment = () => {
        if (parseFloat(amount) === 0) return;
        setShowPaymentModal(true);
    };

    const completeSale = (method: 'cash' | 'card' | 'mobile') => {
        setPaymentMethod(method);

        // Add to history
        const newTx = {
            id: Date.now().toString(),
            item: viewMode === 'grid' ? "Quick Sale" : "Manual Entry",
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            amount: amount,
            method: method
        };
        setTransactions(prev => [newTx, ...prev].slice(0, 5));

        setShowPaymentModal(false);
        setToast({ show: true, message: `Sale Recorded: ${currency === 'ZAR' ? 'R' : '₦'} ${amount}`, type: 'success' });
        setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);

        // Reset or Show Receipt?
        // For speed, we reset immediately but offer receipt in a non-blocking way or simple state reset
        setAmount('0');
        // Optional: Trigger Receipt Modal if needed, but "Fast Transactions" usually means skip receipt unless asked.
    };

    return (
        <div className="space-y-4 h-full flex flex-col">
            <Toast show={toast.show} message={toast.message} type={toast.type} />

            {/* 1. Header & Display */}
            <div className="bg-white rounded-2xl p-4 shadow-sm border border-neutral-200 sticky top-0 z-10">
                <div className="flex justify-between items-center mb-2">
                    <div className="flex space-x-1 bg-neutral-100 p-1 rounded-lg">
                        <button 
                            onClick={() => setViewMode('grid')}
                            className={`px-3 py-1 rounded-md text-xs font-bold transition-colors ${viewMode === 'grid' ? 'bg-white shadow-sm text-brand-600' : 'text-neutral-500'}`}
                        >
                            Favorites
                        </button>
                        <button 
                            onClick={() => setViewMode('keypad')}
                            className={`px-3 py-1 rounded-md text-xs font-bold transition-colors ${viewMode === 'keypad' ? 'bg-white shadow-sm text-brand-600' : 'text-neutral-500'}`}
                        >
                            Keypad
                        </button>
                    </div>
                    <button onClick={() => setAmount('0')} className="text-xs font-bold text-red-500 px-2 py-1 bg-red-50 rounded-lg">CLEAR</button>
                </div>

                <div className="flex justify-between items-end">
                    <span className="text-neutral-400 font-bold text-lg mb-1">{currency}</span>
                    <span className="text-5xl font-extrabold text-neutral-900 tracking-tighter">{parseFloat(amount).toLocaleString()}</span>
                </div>
            </div>

            {/* 2. Input Area (Grid or Keypad) */}
            <div className="flex-1 overflow-y-auto">
                {viewMode === 'grid' ? (
                    <div className="grid grid-cols-3 gap-3 pb-4">
                        {quickItems.map((item) => (
                            <button 
                                key={item.id}
                                onClick={() => addToTotal(item.price)}
                                className="bg-white p-3 rounded-xl border border-neutral-200 shadow-sm active:bg-neutral-50 active:scale-95 transition-all flex flex-col items-center justify-center h-24"
                            >
                                <span className="text-2xl mb-1">{item.icon}</span>
                                <span className="text-xs font-bold text-neutral-700">{item.name}</span>
                                <span className="text-xs font-bold text-brand-600 mt-1">+{item.price}</span>
                            </button>
                        ))}
                        {/* Custom Amount Button for Grid Mode */}
                        <button 
                            onClick={() => setViewMode('keypad')}
                            className="bg-neutral-100 p-3 rounded-xl border border-neutral-200 border-dashed flex flex-col items-center justify-center h-24"
                        >
                            <span className="text-xl text-neutral-400">⌨️</span>
                            <span className="text-xs font-bold text-neutral-500 mt-1">Manual</span>
                        </button>
                    </div>
                ) : (
                    <div className="grid grid-cols-3 gap-3 pb-4">
                         {[1, 2, 3, 4, 5, 6, 7, 8, 9, '.', 0, 'back'].map((item) => (
                            <button 
                                key={item}
                                onClick={() => handleNum(item.toString())}
                                className={`h-16 rounded-xl font-bold text-2xl flex items-center justify-center active:bg-neutral-200 transition-colors ${
                                    item === 'back' ? 'bg-neutral-100 text-neutral-600' : 'bg-white shadow-sm border border-neutral-200 text-neutral-900'
                                }`}
                            >
                                {item === 'back' ? '⌫' : item}
                            </button>
                        ))}
                    </div>
                )}
            </div>

            {/* 3. Checkout Button */}
            <div className="pt-2">
                <Button 
                    fullWidth 
                    size="lg" 
                    onClick={initiatePayment} 
                    disabled={parseFloat(amount) === 0}
                    className="shadow-xl shadow-brand-500/30 text-lg py-5"
                >
                    CHARGE {currency} {amount}
                </Button>
            </div>

             {/* Recent Transactions Mini List */}
             <div className="border-t border-neutral-100 pt-4">
                <h3 className="text-xs font-bold text-neutral-400 uppercase mb-2">Recent</h3>
                <div className="space-y-2">
                    {transactions.map(tx => (
                        <div key={tx.id} className="flex justify-between text-sm">
                            <span className="text-neutral-600">{tx.item} <span className="text-neutral-300 mx-1">•</span> {tx.time}</span>
                            <span className="font-bold text-neutral-900">{tx.amount}</span>
                        </div>
                    ))}
                </div>
             </div>

            {/* Payment Modal */}
            <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Select Payment">
                <div className="grid grid-cols-1 gap-3">
                    <button onClick={() => completeSale('cash')} className="flex items-center p-4 bg-green-50 border border-green-100 rounded-xl active:bg-green-100">
                        <div className="w-10 h-10 bg-green-200 rounded-full flex items-center justify-center text-green-700 mr-4 text-xl">💵</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900">Cash</div>
                            <div className="text-xs text-neutral-500">Collect cash now</div>
                        </div>
                    </button>
                    <button onClick={() => completeSale('mobile')} className="flex items-center p-4 bg-yellow-50 border border-yellow-100 rounded-xl active:bg-yellow-100">
                        <div className="w-10 h-10 bg-yellow-200 rounded-full flex items-center justify-center text-yellow-700 mr-4 text-xl">📱</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900">Mobile Money / E-Wallet</div>
                            <div className="text-xs text-neutral-500">M-Pesa, MoMo, etc.</div>
                        </div>
                    </button>
                    <button onClick={() => completeSale('card')} className="flex items-center p-4 bg-blue-50 border border-blue-100 rounded-xl active:bg-blue-100">
                        <div className="w-10 h-10 bg-blue-200 rounded-full flex items-center justify-center text-blue-700 mr-4 text-xl">💳</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900">Card Machine</div>
                            <div className="text-xs text-neutral-500">Yoco, iKhokha</div>
