import React from 'react';

// --- TYPOGRAPHY TOKENS ---
// Money is always the biggest visual element
const textStyles = {
  h1: "text-3xl font-bold tracking-tight text-neutral-900 leading-tight",
  h2: "text-2xl font-bold tracking-tight text-neutral-900",
  h3: "text-lg font-bold text-neutral-900",
  body: "text-base text-neutral-600 leading-relaxed",
  caption: "text-xs font-medium text-neutral-400 uppercase tracking-wider",
  money: "text-4xl font-extrabold tracking-tight text-neutral-900", // Special token for amounts
};

// --- BUTTONS ---
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'accent' | 'secondary' | 'ghost' | 'outline' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  icon?: React.ReactNode;
  fullWidth?: boolean;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, variant = 'primary', size = 'md', icon, fullWidth = false, className = '', ...props 
}) => {
  const baseStyles = "inline-flex items-center justify-center font-bold transition-all active:scale-[0.98] disabled:opacity-50 disabled:pointer-events-none rounded-2xl";

  const variants = {
    primary: "bg-primary-900 text-white shadow-soft-md hover:bg-primary-700", // Deep Blue (Trust)
    accent: "bg-accent-500 text-white shadow-soft-lg hover:bg-accent-600 shadow-glow", // Green (Money Action)
    secondary: "bg-white text-neutral-900 border border-neutral-200 shadow-soft-sm hover:bg-neutral-50",
    outline: "bg-transparent border-2 border-primary-100 text-primary-900 hover:bg-primary-50",
    ghost: "text-neutral-500 hover:text-neutral-900 hover:bg-neutral-100",
    danger: "bg-danger text-white shadow-soft-md"
  };

  const sizes = {
    sm: "px-4 py-2 text-xs h-8",
    md: "px-6 py-3 text-sm h-12",
    lg: "px-6 py-4 text-base h-[52px]" // Standard Mobile Touch Height
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${sizes[size]} ${fullWidth ? 'w-full' : ''} ${className}`}
      {...props}
    >
      {icon && <span className="mr-2 text-lg">{icon}</span>}
      {children}
    </button>
  );
};

// --- CARDS ---
// Clean, soft shadows, rounded corners
export const Card: React.FC<{ children: React.ReactNode; className?: string; onClick?: () => void; padding?: string }> = ({ children, className = '', onClick, padding = 'p-5' }) => (
  <div 
    onClick={onClick}
    className={`bg-white rounded-2xl border border-neutral-200 shadow-soft-sm relative overflow-hidden ${padding} ${onClick ? 'cursor-pointer transition-transform active:scale-[0.99] hover:border-primary-100' : ''} ${className}`}
  >
    {children}
  </div>
);

// --- INPUTS ---
interface InputProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  icon?: React.ReactNode;
  variant?: 'text' | 'numeric' | 'voice';
}

export const Input: React.FC<InputProps> = ({ label, icon, variant = 'text', className = '', ...props }) => (
  <div className="w-full">
    {label && <label className="block text-xs font-bold text-neutral-500 mb-2 ml-1 uppercase tracking-wide">{label}</label>}
    <div className="relative">
      <input 
        className={`w-full bg-white border border-neutral-200 rounded-xl px-4 h-[48px] shadow-sm focus:ring-2 focus:ring-primary-500 focus:border-transparent text-neutral-900 placeholder-neutral-400 transition-shadow ${icon ? 'pl-11' : ''} ${className}`}
        {...props}
      />
      {icon && (
        <div className="absolute left-4 top-1/2 transform -translate-y-1/2 text-neutral-400 text-lg">
          {icon}
        </div>
      )}
      {variant === 'voice' && (
         <button className="absolute right-3 top-1/2 transform -translate-y-1/2 bg-neutral-100 p-1.5 rounded-lg text-primary-900 hover:bg-neutral-200">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
         </button>
      )}
    </div>
  </div>
);

// --- MODAL ---
export const Modal: React.FC<{ isOpen: boolean; onClose: () => void; title: string; children: React.ReactNode }> = ({ isOpen, onClose, title, children }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-neutral-900/40 backdrop-blur-sm transition-opacity" onClick={onClose}></div>
      <div className="relative bg-white rounded-3xl shadow-soft-lg w-full max-w-md p-6 animate-fade-in-up border border-neutral-100">
        <div className="flex justify-between items-center mb-6">
          <h3 className={textStyles.h3}>{title}</h3>
          <button onClick={onClose} className="w-8 h-8 rounded-full bg-neutral-100 flex items-center justify-center text-neutral-500 hover:text-neutral-900">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>
        {children}
      </div>
    </div>
  );
};

// --- TOAST ---
export const Toast: React.FC<{ message: string; type?: 'success' | 'error' | 'info'; show: boolean }> = ({ message, type = 'info', show }) => {
  if (!show) return null;
  const colors = {
    success: 'bg-accent-500 text-white',
    error: 'bg-danger text-white',
    info: 'bg-primary-900 text-white'
  };
  return (
    <div className={`fixed top-6 left-1/2 transform -translate-x-1/2 px-6 py-3 rounded-full shadow-soft-lg z-50 flex items-center space-x-2 animate-fade-in-down ${colors[type]}`}>
      {type === 'success' && <span className="text-lg">✓</span>}
      <span className="text-sm font-bold">{message}</span>
    </div>
  );
};

// --- BADGE ---
export const Badge: React.FC<{ children: React.ReactNode; variant?: 'success' | 'warning' | 'info' | 'neutral' }> = ({ children, variant = 'neutral' }) => {
  const styles = {
    success: "bg-accent-50 text-accent-600 border border-accent-100",
    warning: "bg-orange-50 text-orange-600 border border-orange-100",
    info: "bg-blue-50 text-blue-600 border border-blue-100",
    neutral: "bg-neutral-100 text-neutral-600 border border-neutral-200"
  };
  return (
    <span className={`inline-flex items-center px-2.5 py-1 rounded-lg text-xs font-bold ${styles[variant]}`}>
      {children}
    </span>
  );
};

// --- AI CHAT BUBBLE ---
export const AIChatBubble: React.FC<{ message: string; isUser: boolean; timestamp: Date; grounding?: any }> = ({ message, isUser, timestamp, grounding }) => {
  return (
    <div className={`flex ${isUser ? 'justify-end' : 'justify-start'} animate-fade-in mb-4`}>
      <div className={`max-w-[85%] rounded-2xl p-4 shadow-sm relative ${
        isUser 
          ? 'bg-primary-900 text-white rounded-br-none' 
          : 'bg-white border border-neutral-200 text-neutral-900 rounded-bl-none'
      }`}>
        <div className="whitespace-pre-wrap text-sm leading-relaxed">{message}</div>

        {grounding?.search && (
          <div className="mt-3 pt-3 border-t border-white/10">
            <p className="text-[10px] font-bold opacity-70 mb-2 uppercase tracking-wide">Sources</p>
            <div className="flex flex-wrap gap-2">
              {grounding.search.map((s: any, idx: number) => (
                <a key={idx} href={s.url} target="_blank" rel="noreferrer" className="bg-black/20 hover:bg-black/30 px-2 py-1 rounded text-[10px] truncate max-w-[150px] text-white/90 block">
                  {s.title}
                </a>
              ))}
            </div>
          </div>
        )}
        <div className={`text-[10px] mt-2 font-medium ${isUser ? 'text-primary-200' : 'text-neutral-400'}`}>
           {timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
        </div>
      </div>
    </div>
  );
};

// --- PROGRESS BAR ---
export const ProgressBar: React.FC<{ progress: number; label?: string; subLabel?: string }> = ({ progress, label, subLabel }) => (
  <div className="w-full">
    {(label || subLabel) && (
      <div className="flex justify-between items-end mb-2">
        {label && <span className="text-xs font-bold text-neutral-500 uppercase tracking-wider">{label}</span>}
        {subLabel && <span className="text-xs font-bold text-accent-600">{subLabel}</span>}
      </div>
    )}
    <div className="w-full bg-neutral-100 rounded-full h-2 overflow-hidden">
      <div 
        className="bg-accent-500 h-full rounded-full transition-all duration-1000 ease-out" 
        style={{ width: `${Math.min(100, Math.max(0, progress))}%` }}
      ></div>
    </div>
  </div>
);

import React, { useState } from 'react';
import { Button, Modal, Toast } from '../components/DesignSystem';

export const Sales: React.FC = () => {
    const [amount, setAmount] = useState('0');
    const [currency] = useState<'ZAR' | 'NGN'>('ZAR');
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });

    // Streamlined Quick Items
    const quickItems = [
        { id: '1', name: 'Bread', price: 18, icon: '🍞' },
        { id: '2', name: 'Milk', price: 22, icon: '🥛' },
        { id: '3', name: 'Coke', price: 15, icon: '🥤' },
        { id: '4', name: 'Airtime', price: 10, icon: '📱' },
        { id: '5', name: 'Chips', price: 12, icon: '🥔' },
        { id: '6', name: 'Meal', price: 45, icon: '🍲' },
    ];

    const addToTotal = (price: number) => {
        setAmount((prev) => (parseFloat(prev) + price).toString());
    };

    const handleClear = () => setAmount('0');

    const initiatePayment = () => {
        if (parseFloat(amount) === 0) return;
        setShowPaymentModal(true);
    };

    const completeSale = (method: string) => {
        setShowPaymentModal(false);
        setToast({ show: true, message: `Paid ${currency} ${amount} via ${method}`, type: 'success' });
        setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
        setAmount('0');
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)]">
            <Toast show={toast.show} message={toast.message} type={toast.type} />

            {/* 1. TOTAL DISPLAY (Always Visible) */}
            <div className="bg-white rounded-2xl p-6 shadow-soft-sm border border-neutral-200 mb-4 flex justify-between items-center relative">
                <div>
                    <p className="text-xs font-bold text-neutral-400 uppercase tracking-wider mb-1">Current Sale</p>
                    <div className="flex items-baseline">
                        <span className="text-2xl font-bold text-neutral-400 mr-2">{currency}</span>
                        <span className="text-5xl font-extrabold text-neutral-900 tracking-tighter">
                            {parseFloat(amount).toLocaleString()}
                        </span>
                    </div>
                </div>
                {parseFloat(amount) > 0 && (
                    <button 
                        onClick={handleClear}
                        className="absolute top-4 right-4 text-xs font-bold text-danger bg-red-50 px-3 py-1 rounded-full hover:bg-red-100"
                    >
                        CLEAR
                    </button>
                )}
            </div>

            {/* 2. PRODUCT GRID (Big Touch Targets) */}
            <div className="flex-1 overflow-y-auto pb-4">
                <div className="grid grid-cols-2 gap-3">
                    {quickItems.map((item) => (
                        <button 
                            key={item.id}
                            onClick={() => addToTotal(item.price)}
                            className="bg-white p-4 rounded-2xl border border-neutral-200 shadow-soft-sm active:bg-neutral-50 active:scale-[0.98] transition-all flex items-center text-left h-24"
                        >
                            <span className="text-3xl mr-3">{item.icon}</span>
                            <div>
                                <span className="text-sm font-bold text-neutral-900 block">{item.name}</span>
                                <span className="text-xs font-bold text-accent-600">+{item.price}</span>
                            </div>
                        </button>
                    ))}
                    {/* Manual Entry */}
                    <button className="bg-neutral-50 p-4 rounded-2xl border-2 border-dashed border-neutral-200 flex items-center justify-center h-24 text-neutral-400">
                        <span className="text-sm font-bold">Manual Keypad</span>
                    </button>
                </div>
            </div>

            {/* 3. ACTION BAR (Sticky Bottom) */}
            <div className="mt-auto pt-2">
                <Button 
                    fullWidth 
                    variant="accent"
                    size="lg" 
                    onClick={initiatePayment} 
                    disabled={parseFloat(amount) === 0}
                    className="text-lg shadow-glow"
                >
                    CHARGE {currency} {amount}
                </Button>
            </div>

            {/* PAYMENT MODAL */}
            <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Select Payment Method">
                <div className="space-y-3">
                    <button onClick={() => completeSale('Cash')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-accent-500 hover:bg-accent-50 transition-colors group">
                        <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💵</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900 text-lg">Cash</div>
                            <div className="text-xs text-neutral-500">Fastest</div>
                        </div>
                    </button>
                    <button onClick={() => completeSale('Card')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-blue-500 hover:bg-blue-50 transition-colors group">
                        <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💳</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900 text-lg">Card / Yoco</div>
                            <div className="text-xs text-neutral-500">Record transaction</div>
                        </div>
                    </button>
                </div>
            </Modal>
        </div>
    );
};

import React, { useState } from 'react';
import { Button, Input, ProgressBar } from '../../components/DesignSystem';

interface OnboardingProps {
  onComplete: () => void;
  onLogin: () => void;
}

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete, onLogin }) => {
  const [step, setStep] = useState(1);
  const totalSteps = 4;
  const progress = (step / totalSteps) * 100;

  const nextStep = () => setStep(prev => Math.min(prev + 1, totalSteps));

  // STEP 1: WELCOME & LANGUAGE
  const renderStep1 = () => (
    <div className="text-center space-y-8 animate-fade-in">
      <div className="w-24 h-24 bg-primary-900 rounded-3xl flex items-center justify-center mx-auto shadow-soft-lg">
        <span className="text-4xl font-bold text-white">I</span>
      </div>

      <div>
        <h1 className="text-3xl font-extrabold text-neutral-900 mb-3">Welcome to IBOS</h1>
        <p className="text-neutral-500 text-lg leading-relaxed">
          The professional operating system for your business.
        </p>
      </div>

      <div className="grid grid-cols-3 gap-3 max-w-xs mx-auto">
          <button className="py-2 px-4 bg-primary-50 text-primary-900 rounded-xl text-sm font-bold ring-2 ring-primary-900">English</button>
          <button className="py-2 px-4 bg-white border border-neutral-200 text-neutral-500 rounded-xl text-sm font-bold">Zulu</button>
          <button className="py-2 px-4 bg-white border border-neutral-200 text-neutral-500 rounded-xl text-sm font-bold">Xhosa</button>
      </div>

      <div className="pt-4">
        <Button fullWidth size="lg" variant="primary" onClick={nextStep}>
          Get Started
        </Button>
        <button onClick={onLogin} className="mt-6 text-sm font-bold text-primary-900 hover:underline">
            Log in to existing account
        </button>
      </div>
    </div>
  );

  // STEP 2: BUSINESS IDENTITY
  const renderStep2 = () => (
    <div className="space-y-6 animate-fade-in">
       <div className="text-center mb-6">
         <h2 className="text-2xl font-bold text-neutral-900">What do you trade?</h2>
         <p className="text-neutral-500 text-sm">We'll set up your quick buttons.</p>
       </div>

       <div className="grid grid-cols-1 gap-4">
            {[
                { label: 'Retail Shop / Spaza', icon: '🏪', desc: 'Bread, Milk, Airtime' },
                { label: 'Fruits & Veg', icon: '🍎', desc: 'Fresh produce, loose stock' },
                { label: 'Services / Salon', icon: '✂️', desc: 'Haircuts, Repairs, Labour' },
                { label: 'Food Stall', icon: '🍲', desc: 'Plates, Kotas, Drinks' },
            ].map((type, i) => (
                <button
                    key={i}
                    onClick={nextStep}
                    className="flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-primary-500 hover:shadow-soft-md transition-all text-left group"
                >
                    <div className="w-12 h-12 bg-neutral-50 rounded-full flex items-center justify-center text-2xl mr-4 group-hover:bg-primary-50">
                        {type.icon}
                    </div>
                    <div>
                        <div className="font-bold text-neutral-900">{type.label}</div>
                        <div className="text-xs text-neutral-500">{type.desc}</div>
                    </div>
                </button>
            ))}
       </div>
    </div>
  );

  // STEP 3: FIRST SALE (The "Aha" Moment)
  const renderStep3 = () => (
    <div className="space-y-8 animate-fade-in text-center">
        <div>
            <div className="w-16 h-16 bg-accent-50 text-accent-600 rounded-full flex items-center justify-center mx-auto mb-4">
                <span className="text-2xl">💰</span>
            </div>
            <h2 className="text-2xl font-bold text-neutral-900">Record your first sale</h2>
            <p className="text-neutral-500 text-sm mt-2">No typing needed. Just enter value.</p>
        </div>

        <div className="bg-white p-8 rounded-3xl shadow-soft-md border border-neutral-200 max-w-xs mx-auto">
             <div className="text-xs font-bold text-neutral-400 uppercase tracking-wider mb-2">Amount (ZAR)</div>
             <input 
                type="number" 
                className="text-5xl font-extrabold text-neutral-900 text-center w-full focus:outline-none placeholder-neutral-200 bg-transparent"
                placeholder="0"
                autoFocus
             />
        </div>

        <Button fullWidth size="lg" variant="accent" onClick={nextStep} className="shadow-glow">
            Record Sale
        </Button>
    </div>
  );

  // STEP 4: ACCOUNT SECURE
  const renderStep4 = () => (
    <div className="space-y-6 animate-fade-in">
        <div className="text-center mb-6">
            <h2 className="text-2xl font-bold text-neutral-900">Save your business</h2>
            <p className="text-neutral-500 text-sm">Secure your data with a phone number.</p>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-neutral-200 space-y-4 shadow-soft-sm">
             <Input label="Business Name" placeholder="e.g. Mama Dlamini Spaza" />
             <Input label="Phone Number" placeholder="e.g. 072 123 4567" type="tel" icon={<span>📞</span>} />
             <Button fullWidth size="lg" variant="primary" onClick={onComplete}>
                Complete Setup
             </Button>
        </div>

        <button onClick={onComplete} className="w-full py-3 text-neutral-400 text-xs font-bold uppercase tracking-wider hover:text-neutral-600">
            Skip for now
        </button>
    </div>
  );

  return (
    <div className="min-h-screen bg-neutral-50 flex flex-col">
       {/* Minimal Progress Bar */}
       {step > 1 && (
         <div className="w-full h-1 bg-neutral-200">
            <div className="h-full bg-primary-900 transition-all duration-500" style={{ width: `${progress}%` }}></div>
         </div>
       )}

       <div className="flex-1 flex flex-col justify-center p-6 max-w-md mx-auto w-full">
         {step > 1 && (
            <button onClick={() => setStep(step - 1)} className="self-start mb-6 text-neutral-400 hover:text-neutral-900 p-2 -ml-2">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
            </button>
         )}

         {step === 1 && renderStep1()}
         {step === 2 && renderStep2()}
         {step === 3 && renderStep3()}
         {step === 4 && renderStep4()}
       </div>
    </div>
  );
};

