📱 IBOS – Clickable UX Prototype (HTML)
How to use

Copy all code below

Save as: ibos-prototype.html

Open in browser

Click around like a real app

✅ Features Included

Clickable flows:

Home dashboard

New Sale (POS)

Add Stock

Add Expense

Finance overview

Bottom navigation

Screen transitions

💻 Prototype Code
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1.0"/>
<title>IBOS Prototype</title>

<style>
:root{
  --primary:#0B3C5D;
  --success:#00B386;
  --bg:#F6F8FA;
  --card:#FFFFFF;
  --text:#111827;
  --radius:16px;
}

body{
  margin:0;
  font-family:system-ui, -apple-system, Roboto, sans-serif;
  background:var(--bg);
}

.app{
  max-width:420px;
  height:100vh;
  margin:auto;
  display:flex;
  flex-direction:column;
  background:#fff;
  position:relative;
}

.screen{
  display:none;
  flex:1;
  padding:16px;
  overflow:auto;
}

.active{ display:block; }

h1{ font-size:22px; margin-bottom:12px; }

.card{
  background:var(--card);
  padding:16px;
  border-radius:var(--radius);
  margin-bottom:12px;
  box-shadow:0 2px 6px rgba(0,0,0,.08);
}

.money{
  font-size:32px;
  font-weight:700;
  color:var(--success);
}

.btn{
  height:48px;
  border:none;
  border-radius:14px;
  background:var(--primary);
  color:white;
  width:100%;
  margin-top:10px;
  font-size:16px;
}

.grid{
  display:grid;
  grid-template-columns:repeat(2,1fr);
  gap:10px;
}

.product{
  padding:20px;
  background:#eee;
  border-radius:14px;
  text-align:center;
}

.nav{
  display:flex;
  height:60px;
  border-top:1px solid #ddd;
}

.nav button{
  flex:1;
  border:none;
  background:white;
  font-size:12px;
}
</style>
</head>

<body>

<div class="app">

<!-- HOME -->
<div id="home" class="screen active">
  <h1>Dashboard</h1>

  <div class="card">
    <div>Today’s Sales</div>
    <div class="money">R 3,540</div>
  </div>

  <div class="grid">
    <button class="btn" onclick="go('sales')">New Sale</button>
    <button class="btn" onclick="go('trade')">Add Stock</button>
    <button class="btn" onclick="go('finance')">Finance</button>
    <button class="btn" onclick="go('expense')">Expense</button>
  </div>
</div>


<!-- SALES POS -->
<div id="sales" class="screen">
  <h1>New Sale</h1>

  <div class="grid">
    <div class="product" onclick="add(10)">Bread R10</div>
    <div class="product" onclick="add(15)">Milk R15</div>
    <div class="product" onclick="add(12)">Eggs R12</div>
    <div class="product" onclick="add(8)">Coke R8</div>
  </div>

  <div class="card">
    Total: <span id="total">R 0</span>
    <button class="btn" onclick="pay()">Pay</button>
  </div>
</div>


<!-- TRADE -->
<div id="trade" class="screen">
  <h1>Add Stock</h1>

  <div class="card">
    <input placeholder="Item name" style="width:100%;height:40px"><br><br>
    <input placeholder="Quantity" style="width:100%;height:40px"><br>
    <button class="btn" onclick="alert('Saved!')">Save Stock</button>
  </div>
</div>


<!-- FINANCE -->
<div id="finance" class="screen">
  <h1>Finance</h1>

  <div class="card">Income: R 12,000</div>
  <div class="card">Expenses: R 7,200</div>
  <div class="card money">Profit: R 4,800</div>

  <button class="btn" onclick="alert('Loan requested!')">Request Loan</button>
</div>


<!-- EXPENSE -->
<div id="expense" class="screen">
  <h1>Add Expense</h1>

  <div class="card">
    <input placeholder="Amount" style="width:100%;height:40px"><br><br>
    <button class="btn" onclick="alert('Expense saved')">Save</button>
  </div>
</div>


<!-- NAVIGATION -->
<div class="nav">
  <button onclick="go('home')">Home</button>
  <button onclick="go('sales')">Sales</button>
  <button onclick="go('trade')">Trade</button>
  <button onclick="go('finance')">Finance</button>
</div>

</div>


<script>
let total = 0;

function go(id){
  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));
  document.getElementById(id).classList.add('active');
}

function add(price){
  total += price;
  document.getElementById('total').innerText = "R " + total;
}

function pay(){
  alert("Payment Successful!");
  total = 0;
  go('home');
}
</script>

</body>
</html>

