// STORAGE KEYS
const KEYS = {
  INVENTORY: 'ibos_inventory',
  SALES: 'ibos_sales',
  EXPENSES: 'ibos_expenses',
  SYNC_QUEUE: 'ibos_sync_queue',
};

// INITIAL SEED DATA (If app is fresh)
const SEED_INVENTORY: InventoryItem[] = [
  { id: '1', name: 'Brown Bread', price: 18, cost: 12, quantity: 15, category: 'Bakery', icon: '🍞', lowStockThreshold: 5 },
  { id: '2', name: 'Full Cream Milk', price: 22, cost: 16, quantity: 8, category: 'Dairy', icon: '🥛', lowStockThreshold: 3 },
  { id: '3', name: 'Coke (500ml)', price: 15, cost: 9, quantity: 24, category: 'Beverages', icon: '🥤', lowStockThreshold: 10 },
  { id: '4', name: 'Airtime (MTN)', price: 10, cost: 9.5, quantity: 100, category: 'Services', icon: '📱' },
  { id: '5', name: 'Lays Chips', price: 12, cost: 8, quantity: 5, category: 'Snacks', icon: '🥔', lowStockThreshold: 5 },
  { id: '6', name: 'Plate (Chicken)', price: 45, cost: 25, quantity: 20, category: 'Food', icon: '🍲' },
];

class LocalStorageService {
  constructor() {
    this.init();
  }

  private init() {
    if (!localStorage.getItem(KEYS.INVENTORY)) {
      localStorage.setItem(KEYS.INVENTORY, JSON.stringify(SEED_INVENTORY));
    }
    if (!localStorage.getItem(KEYS.SALES)) {
      localStorage.setItem(KEYS.SALES, JSON.stringify([]));
    }
    if (!localStorage.getItem(KEYS.EXPENSES)) {
      localStorage.setItem(KEYS.EXPENSES, JSON.stringify([]));
    }
    if (!localStorage.getItem(KEYS.SYNC_QUEUE)) {
      localStorage.setItem(KEYS.SYNC_QUEUE, JSON.stringify([]));
    }
  }

  // --- INVENTORY ---
  getInventory(): InventoryItem[] {
    const data = localStorage.getItem(KEYS.INVENTORY);
    return data ? JSON.parse(data) : [];
  }

  addInventoryItem(item: InventoryItem) {
    const items = this.getInventory();
    items.push(item);
    localStorage.setItem(KEYS.INVENTORY, JSON.stringify(items));
    this.addToSyncQueue({ type: 'INVENTORY_ADD', payload: item });
  }

  updateStock(id: string, delta: number) {
    const items = this.getInventory();
    const index = items.findIndex(i => i.id === id);
    if (index !== -1) {
      items[index].quantity += delta;
      localStorage.setItem(KEYS.INVENTORY, JSON.stringify(items));
    }
  }

  // --- SALES ---
  getSales(): Sale[] {
    const data = localStorage.getItem(KEYS.SALES);
    return data ? JSON.parse(data) : [];
  }

  addSale(sale: Sale) {
    const sales = this.getSales();
    sales.unshift(sale); // Add to top
    localStorage.setItem(KEYS.SALES, JSON.stringify(sales));

    // Deduct stock
    sale.items.forEach(item => {
      this.updateStock(item.productId, -item.quantity);
    });

    this.addToSyncQueue({ type: 'SALE_CREATE', payload: sale });
  }

  // --- EXPENSES ---
  getExpenses(): Expense[] {
    const data = localStorage.getItem(KEYS.EXPENSES);
    return data ? JSON.parse(data) : [];
  }

  addExpense(expense: Expense) {
    const expenses = this.getExpenses();
    expenses.unshift(expense);
    localStorage.setItem(KEYS.EXPENSES, JSON.stringify(expenses));
    this.addToSyncQueue({ type: 'EXPENSE_CREATE', payload: expense });
  }

  // --- SYNC QUEUE ---
  getSyncQueue(): any[] {
    const data = localStorage.getItem(KEYS.SYNC_QUEUE);
    return data ? JSON.parse(data) : [];
  }

  addToSyncQueue(action: any) {
    const queue = this.getSyncQueue();
    queue.push({ ...action, timestamp: Date.now() });
    localStorage.setItem(KEYS.SYNC_QUEUE, JSON.stringify(queue));
  }

  clearSyncQueue() {
    localStorage.setItem(KEYS.SYNC_QUEUE, JSON.stringify([]));
  }

  // --- ANALYTICS ---
  getFinancialSummary() {
    const sales = this.getSales();
    const expenses = this.getExpenses();

    // Simple filter for "This Week" (Mock logic: just taking all for demo)
    const totalRevenue = sales.reduce((sum, s) => sum + s.total, 0);
    const totalExpenses = expenses.reduce((sum, e) => sum + e.amount, 0);
    const profit = totalRevenue - totalExpenses;

    return { totalRevenue, totalExpenses, profit };
  }
}

export const db = new LocalStorageService();

import { db } from './storage';

class SyncEngine {
  private isSyncing = false;
  private intervalId: any;

  start() {
    if (this.intervalId) return;
    // Try to sync every 10 seconds (simulating background worker)
    this.intervalId = setInterval(() => this.sync(), 10000);
  }

  stop() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }

  async sync() {
    if (this.isSyncing || !navigator.onLine) return;

    const queue = db.getSyncQueue();
    if (queue.length === 0) return;

    this.isSyncing = true;
    console.log(`[SyncEngine] Processing ${queue.length} items...`);

    try {
      // SIMULATE NETWORK REQUEST
      await new Promise(resolve => setTimeout(resolve, 1500));

      // On success, clear queue (in real app, remove specific items)
      db.clearSyncQueue();
      console.log('[SyncEngine] Sync complete.');

      // Dispatch event to update UI if needed
      window.dispatchEvent(new Event('ibos-sync-complete'));

    } catch (error) {
      console.error('[SyncEngine] Failed:', error);
    } finally {
      this.isSyncing = false;
    }
  }
}

export const syncEngine = new SyncEngine();

import React, { useState, useEffect } from 'react';
import { Button, Modal, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { InventoryItem, SaleItem } from '../types';

export const Sales: React.FC = () => {
    const [amount, setAmount] = useState(0);
    const [cart, setCart] = useState<SaleItem[]>([]);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [currency] = useState<'ZAR' | 'NGN'>('ZAR');
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });

    // Load inventory from DB on mount
    useEffect(() => {
        setInventory(db.getInventory());
    }, []);

    const addToCart = (item: InventoryItem) => {
        setCart(prev => {
            const existing = prev.find(i => i.productId === item.id);
            if (existing) {
                return prev.map(i => i.productId === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { productId: item.id, name: item.name, price: item.price, quantity: 1 }];
        });
        setAmount(prev => prev + item.price);
    };

    const handleClear = () => {
        setAmount(0);
        setCart([]);
    };

    const initiatePayment = () => {
        if (amount === 0) return;
        setShowPaymentModal(true);
    };

    const completeSale = (method: string) => {
        // 1. Create Sale Object
        const sale = {
            id: Date.now().toString(),
            items: cart,
            total: amount,
            currency,
            method,
            timestamp: Date.now(),
            synced: false
        };

        // 2. Save to Local DB (Instant)
        db.addSale(sale);

        // 3. Update UI Inventory (Optimistic)
        setInventory(prev => prev.map(invItem => {
            const cartItem = cart.find(c => c.productId === invItem.id);
            if (cartItem) {
                return { ...invItem, quantity: invItem.quantity - cartItem.quantity };
            }
            return invItem;
        }));

        // 4. Reset & Feedback
        setShowPaymentModal(false);
        setToast({ show: true, message: `Paid ${currency} ${amount} via ${method}`, type: 'success' });
        setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
        handleClear();
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)]">
            <Toast show={toast.show} message={toast.message} type={toast.type} />

            {/* 1. TOTAL DISPLAY */}
            <div className="bg-white rounded-2xl p-6 shadow-soft-sm border border-neutral-200 mb-4 flex justify-between items-center relative">
                <div>
                    <p className="text-xs font-bold text-neutral-400 uppercase tracking-wider mb-1">Current Sale</p>
                    <div className="flex items-baseline">
                        <span className="text-2xl font-bold text-neutral-400 mr-2">{currency}</span>
                        <span className="text-5xl font-extrabold text-neutral-900 tracking-tighter">
                            {amount.toLocaleString()}
                        </span>
                    </div>
                </div>
                {amount > 0 && (
                    <button 
                        onClick={handleClear}
                        className="absolute top-4 right-4 text-xs font-bold text-danger bg-red-50 px-3 py-1 rounded-full hover:bg-red-100"
                    >
                        CLEAR
                    </button>
                )}
            </div>

            {/* 2. PRODUCT GRID (From DB) */}
            <div className="flex-1 overflow-y-auto pb-4">
                <div className="grid grid-cols-2 gap-3">
                    {inventory.map((item) => (
                        <button 
                            key={item.id}
                            onClick={() => addToCart(item)}
                            className="bg-white p-4 rounded-2xl border border-neutral-200 shadow-soft-sm active:bg-neutral-50 active:scale-[0.98] transition-all flex items-center text-left h-24 relative overflow-hidden"
                        >
                            <span className="text-3xl mr-3">{item.icon || '📦'}</span>
                            <div className="flex-1 min-w-0">
                                <span className="text-sm font-bold text-neutral-900 block truncate">{item.name}</span>
                                <span className="text-xs font-bold text-accent-600">R {item.price}</span>
                                {item.quantity <= (item.lowStockThreshold || 0) && (
                                    <span className="text-[10px] text-danger font-bold block">Low: {item.quantity}</span>
                                )}
                            </div>
                            {/* Quantity Badge in Cart */}
                            {cart.find(c => c.productId === item.id) && (
                                <div className="absolute top-2 right-2 bg-primary-900 text-white text-[10px] font-bold w-5 h-5 rounded-full flex items-center justify-center">
                                    {cart.find(c => c.productId === item.id)?.quantity}
                                </div>
                            )}
                        </button>
                    ))}
                    {/* Manual Entry */}
                    <button className="bg-neutral-50 p-4 rounded-2xl border-2 border-dashed border-neutral-200 flex items-center justify-center h-24 text-neutral-400">
                        <span className="text-sm font-bold">Manual Keypad</span>
                    </button>
                </div>
            </div>

            {/* 3. ACTION BAR */}
            <div className="mt-auto pt-2">
                <Button 
                    fullWidth 
                    variant="accent"
                    size="lg" 
                    onClick={initiatePayment} 
                    disabled={amount === 0}
                    className="text-lg shadow-glow"
                >
                    CHARGE {currency} {amount}
                </Button>
            </div>

            {/* PAYMENT MODAL */}
            <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Select Payment Method">
                <div className="space-y-3">
                    <button onClick={() => completeSale('Cash')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-accent-500 hover:bg-accent-50 transition-colors group">
                        <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💵</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900 text-lg">Cash</div>
                            <div className="text-xs text-neutral-500">Fastest</div>
                        </div>
                    </button>
                    <button onClick={() => completeSale('Card')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-blue-500 hover:bg-blue-50 transition-colors group">
                        <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💳</div>
                        <div className="text-left">
                            <div className="font-bold text-neutral-900 text-lg">Card / Yoco</div>
                            <div className="text-xs text-neutral-500">Record transaction</div>
                        </div>
                    </button>
                </div>
            </Modal>
        </div>
    );
};

