import React, { useState, useEffect } from 'react';
import { Button, Modal, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { InventoryItem, SaleItem } from '../types';
import QRCode from 'qrcode';

export const Sales: React.FC = () => {
    const [amount, setAmount] = useState(0);
    const [cart, setCart] = useState<SaleItem[]>([]);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [currency] = useState<'ZAR' | 'NGN'>('ZAR');
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });

    // QR Code State
    const [qrCodeUrl, setQrCodeUrl] = useState<string | null>(null);
    const [isGeneratingQR, setIsGeneratingQR] = useState(false);

    // Load inventory from DB on mount
    useEffect(() => {
        setInventory(db.getInventory());
    }, []);

    const addToCart = (item: InventoryItem) => {
        setCart(prev => {
            const existing = prev.find(i => i.productId === item.id);
            if (existing) {
                return prev.map(i => i.productId === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { productId: item.id, name: item.name, price: item.price, quantity: 1 }];
        });
        setAmount(prev => prev + item.price);
    };

    const handleClear = () => {
        setAmount(0);
        setCart([]);
        setQrCodeUrl(null);
    };

    const initiatePayment = () => {
        if (amount === 0) return;
        setQrCodeUrl(null); // Reset QR state
        setShowPaymentModal(true);
    };

    const generatePaymentQR = async () => {
        setIsGeneratingQR(true);
        try {
            const transactionId = `txn_${Date.now()}`;
            const paymentData = {
                id: transactionId,
                amount: amount,
                currency: currency,
                merchant: "IBOS Merchant",
                items: cart.map(i => ({ name: i.name, qty: i.quantity }))
            };

            const url = await QRCode.toDataURL(JSON.stringify(paymentData), {
                width: 256,
                margin: 2,
                color: {
                    dark: '#0B3C5D', // Primary brand color
                    light: '#FFFFFF'
                }
            });
            setQrCodeUrl(url);
        } catch (err) {
            console.error("QR Gen Error", err);
            setToast({ show: true, message: 'Could not generate QR code', type: 'error' });
        } finally {
            setIsGeneratingQR(false);
        }
    };

    const completeSale = (method: string) => {
        // 1. Create Sale Object
        const sale = {
            id: Date.now().toString(),
            items: cart,
            total: amount,
            currency,
            method,
            timestamp: Date.now(),
            synced: false
        };

        // 2. Save to Local DB (Instant)
        db.addSale(sale);

        // 3. Update UI Inventory (Optimistic)
        setInventory(prev => prev.map(invItem => {
            const cartItem = cart.find(c => c.productId === invItem.id);
            if (cartItem) {
                return { ...invItem, quantity: invItem.quantity - cartItem.quantity };
            }
            return invItem;
        }));

        // 4. Reset & Feedback
        setShowPaymentModal(false);
        setQrCodeUrl(null);
        setToast({ show: true, message: `Paid ${currency} ${amount} via ${method}`, type: 'success' });
        setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
        handleClear();
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)]">
            <Toast show={toast.show} message={toast.message} type={toast.type} />

            {/* 1. TOTAL DISPLAY */}
            <div className="bg-white rounded-2xl p-6 shadow-soft-sm border border-neutral-200 mb-4 flex justify-between items-center relative">
                <div>
                    <p className="text-xs font-bold text-neutral-400 uppercase tracking-wider mb-1">Current Sale</p>
                    <div className="flex items-baseline">
                        <span className="text-2xl font-bold text-neutral-400 mr-2">{currency}</span>
                        <span className="text-5xl font-extrabold text-neutral-900 tracking-tighter">
                            {amount.toLocaleString()}
                        </span>
                    </div>
                </div>
                {amount > 0 && (
                    <button 
                        onClick={handleClear}
                        className="absolute top-4 right-4 text-xs font-bold text-danger bg-red-50 px-3 py-1 rounded-full hover:bg-red-100"
                    >
                        CLEAR
                    </button>
                )}
            </div>

            {/* 2. PRODUCT GRID (From DB) */}
            <div className="flex-1 overflow-y-auto pb-4">
                <div className="grid grid-cols-2 gap-3">
                    {inventory.map((item) => (
                        <button 
                            key={item.id}
                            onClick={() => addToCart(item)}
                            className="bg-white p-4 rounded-2xl border border-neutral-200 shadow-soft-sm active:bg-neutral-50 active:scale-[0.98] transition-all flex items-center text-left h-24 relative overflow-hidden"
                        >
                            <span className="text-3xl mr-3">{item.icon || '📦'}</span>
                            <div className="flex-1 min-w-0">
                                <span className="text-sm font-bold text-neutral-900 block truncate">{item.name}</span>
                                <span className="text-xs font-bold text-accent-600">R {item.price}</span>
                                {item.quantity <= (item.lowStockThreshold || 0) && (
                                    <span className="text-[10px] text-danger font-bold block">Low: {item.quantity}</span>
                                )}
                            </div>
                            {/* Quantity Badge in Cart */}
                            {cart.find(c => c.productId === item.id) && (
                                <div className="absolute top-2 right-2 bg-primary-900 text-white text-[10px] font-bold w-5 h-5 rounded-full flex items-center justify-center">
                                    {cart.find(c => c.productId === item.id)?.quantity}
                                </div>
                            )}
                        </button>
                    ))}
                    {/* Manual Entry */}
                    <button className="bg-neutral-50 p-4 rounded-2xl border-2 border-dashed border-neutral-200 flex items-center justify-center h-24 text-neutral-400">
                        <span className="text-sm font-bold">Manual Keypad</span>
                    </button>
                </div>
            </div>

            {/* 3. ACTION BAR */}
            <div className="mt-auto pt-2">
                <Button 
                    fullWidth 
                    variant="accent"
                    size="lg" 
                    onClick={initiatePayment} 
                    disabled={amount === 0}
                    className="text-lg shadow-glow"
                >
                    CHARGE {currency} {amount}
                </Button>
            </div>

            {/* PAYMENT MODAL */}
            <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Select Payment Method">
                <div className="space-y-3">
                    {!qrCodeUrl ? (
                        <>
                            <button onClick={() => completeSale('Cash')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-accent-500 hover:bg-accent-50 transition-colors group">
                                <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💵</div>
                                <div className="text-left">
                                    <div className="font-bold text-neutral-900 text-lg">Cash</div>
                                    <div className="text-xs text-neutral-500">Fastest</div>
                                </div>
                            </button>
                            <button onClick={() => completeSale('Card')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-blue-500 hover:bg-blue-50 transition-colors group">
                                <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💳</div>
                                <div className="text-left">
                                    <div className="font-bold text-neutral-900 text-lg">Card / Yoco</div>
                                    <div className="text-xs text-neutral-500">Record transaction</div>
                                </div>
                            </button>
                            <button onClick={generatePaymentQR} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-neutral-900 hover:bg-neutral-50 transition-colors group">
                                <div className="w-12 h-12 rounded-full bg-neutral-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">📱</div>
                                <div className="text-left">
                                    <div className="font-bold text-neutral-900 text-lg">Scan to Pay</div>
                                    <div className="text-xs text-neutral-500">Generate QR Code</div>
                                </div>
                            </button>
                        </>
                    ) : (
                        <div className="text-center animate-fade-in">
                            <div className="bg-white p-4 rounded-2xl border border-neutral-200 shadow-sm inline-block mb-4">
                                <img src={qrCodeUrl} alt="Payment QR" className="w-48 h-48" />
                            </div>
                            <p className="text-sm font-bold text-neutral-600 mb-4">Scan to pay R {amount}</p>
                            <div className="flex space-x-3">
                                <Button fullWidth variant="secondary" onClick={() => setQrCodeUrl(null)}>Back</Button>
                                <Button fullWidth variant="accent" onClick={() => completeSale('QR Payment')}>Confirm Payment</Button>
                            </div>
                        </div>
                    )}
                </div>
            </Modal>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Button, Modal, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { InventoryItem, SaleItem, Sale } from '../types';
import QRCode from 'qrcode';

const RATE_NGN = 85; // 1 ZAR = ~85 NGN

export const Sales: React.FC = () => {
    const [amount, setAmount] = useState(0);
    const [cart, setCart] = useState<SaleItem[]>([]);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [currency, setCurrency] = useState<'ZAR' | 'NGN'>('ZAR');

    // UI State
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });

    // QR Code State
    const [qrCodeUrl, setQrCodeUrl] = useState<string | null>(null);
    const [isGeneratingQR, setIsGeneratingQR] = useState(false);

    // Load inventory from DB on mount
    useEffect(() => {
        setInventory(db.getInventory());
    }, []);

    // Helper: Format Price based on Currency
    const formatPrice = (val: number, showSymbol = true) => {
        if (currency === 'NGN') {
            const converted = val * RATE_NGN;
            return showSymbol ? `₦ ${converted.toLocaleString()}` : converted.toLocaleString();
        }
        return showSymbol ? `R ${val.toLocaleString()}` : val.toLocaleString();
    };

    const addToCart = (item: InventoryItem) => {
        setCart(prev => {
            const existing = prev.find(i => i.productId === item.id);
            if (existing) {
                return prev.map(i => i.productId === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { productId: item.id, name: item.name, price: item.price, quantity: 1 }];
        });
        setAmount(prev => prev + item.price);
    };

    const handleClear = () => {
        setAmount(0);
        setCart([]);
        setQrCodeUrl(null);
    };

    const handleNewSale = () => {
        handleClear();
        setLastSale(null);
        setShowSuccessModal(false);
    };

    const initiatePayment = () => {
        if (amount === 0) return;
        setQrCodeUrl(null); // Reset QR state
        setShowPaymentModal(true);
    };

    const generatePaymentQR = async () => {
        setIsGeneratingQR(true);
        try {
            const transactionId = `txn_${Date.now()}`;
            const displayAmount = currency === 'NGN' ? amount * RATE_NGN : amount;

            const paymentData = {
                id: transactionId,
                amount: displayAmount,
                currency: currency,
                merchant: "IBOS Merchant",
                items: cart.map(i => ({ name: i.name, qty: i.quantity }))
            };

            const url = await QRCode.toDataURL(JSON.stringify(paymentData), {
                width: 256,
                margin: 2,
                color: {
                    dark: '#0B3C5D', // Primary brand color
                    light: '#FFFFFF'
                }
            });
            setQrCodeUrl(url);
        } catch (err) {
            console.error("QR Gen Error", err);
            setToast({ show: true, message: 'Could not generate QR code', type: 'error' });
        } finally {
            setIsGeneratingQR(false);
        }
    };

    const completeSale = (method: string) => {
        // 1. Create Sale Object
        const sale: Sale = {
            id: Date.now().toString(),
            items: cart,
            total: amount, // Store base ZAR amount
            currency, // Store currency used for transaction
            method,
            timestamp: Date.now(),
            synced: false
        };

        // 2. Save to Local DB (Instant)
        db.addSale(sale);

        // 3. Update UI Inventory (Optimistic)
        setInventory(prev => prev.map(invItem => {
            const cartItem = cart.find(c => c.productId === invItem.id);
            if (cartItem) {
                return { ...invItem, quantity: invItem.quantity - cartItem.quantity };
            }
            return invItem;
        }));

        // 4. Show Success
        setLastSale(sale);
        setShowPaymentModal(false);
        setShowSuccessModal(true);
        setQrCodeUrl(null);
    };

    const shareInvoiceWhatsApp = () => {
        if (!lastSale) return;

        const date = new Date(lastSale.timestamp).toLocaleDateString();
        const time = new Date(lastSale.timestamp).toLocaleTimeString();

        // Calculate display total based on the currency used during sale
        const isNgn = lastSale.currency === 'NGN';
        const rate = isNgn ? RATE_NGN : 1;
        const symbol = isNgn ? '₦' : 'R';
        const displayTotal = (lastSale.total * rate).toLocaleString();

        let message = `🧾 *INVOICE - IBOS Merchant*\n`;
        message += `📅 ${date} at ${time}\n`;
        message += `🆔 ${lastSale.id.slice(-6)}\n\n`;
        message += `*ITEMS:*\n`;
        lastSale.items.forEach(item => {
             const p = item.price * rate;
             message += `${item.quantity}x ${item.name} (${symbol}${p.toLocaleString()})\n`;
        });
        message += `\n*TOTAL: ${symbol} ${displayTotal}*\n`;
        message += `Paid via: ${lastSale.method}\n\n`;
        message += `Thank you for your business!`;

        const url = `https://wa.me/?text=${encodeURIComponent(message)}`;
        window.open(url, '_blank');
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)]">
            <Toast show={toast.show} message={toast.message} type={toast.type} />

            {/* 1. TOTAL DISPLAY */}
            <div className="bg-white rounded-2xl p-6 shadow-soft-sm border border-neutral-200 mb-4 flex justify-between items-center relative">
