import React, { useState } from 'react';
import { Layout } from './components/Layout';
import { Dashboard } from './pages/Dashboard';
import { SmartAssistant } from './pages/SmartAssistant';
import { Tools } from './pages/Tools';
import { SystemDesign } from './pages/SystemDesign';
import { Sales } from './pages/Sales';
import { Trade } from './pages/Trade';
import { Finance } from './pages/Finance';
import { Compliance } from './pages/Compliance';
import { AppRoute } from './types';
import { ReceiptScanner } from './pages/Tools/ReceiptScanner';
import { InventoryVideo } from './pages/Tools/InventoryVideo';
import { BusinessStrategy } from './pages/Tools/BusinessStrategy';
import { Login } from './pages/Auth/Login';
import { Onboarding } from './pages/Auth/Onboarding';

const App: React.FC = () => {
  // Auth State: 'ONBOARDING' is default for demo to show the flow
  const [authView, setAuthView] = useState<'LOGIN' | 'ONBOARDING' | 'APP'>('ONBOARDING');

  const [route, setRoute] = useState<AppRoute>(AppRoute.DASHBOARD);
  const [activeTool, setActiveTool] = useState<string | null>(null);

  const handleAuthComplete = () => {
    setAuthView('APP');
  };

  if (authView === 'LOGIN') {
    return <Login onLogin={handleAuthComplete} onGoToSignup={() => setAuthView('ONBOARDING')} />;
  }

  if (authView === 'ONBOARDING') {
    return <Onboarding onComplete={handleAuthComplete} onLogin={() => setAuthView('LOGIN')} />;
  }

  const renderContent = () => {
    // Legacy Tool Routing Logic
    if (activeTool) {
      return (
        <div className="space-y-4">
           <button 
             onClick={() => setActiveTool(null)} 
             className="flex items-center text-sm text-gray-500 hover:text-gray-800"
           >
             <svg className="w-4 h-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
             Back to Tools
           </button>
           {activeTool === 'receipt_scanner' && <ReceiptScanner />}
           {activeTool === 'inventory_video' && <InventoryVideo />}
           {activeTool === 'business_strategy' && <BusinessStrategy />}
           {activeTool === 'quick_calc' && <div className="p-4 bg-yellow-50 rounded text-center text-yellow-800">Use the Smart Assistant for Quick Calculations!</div>}
        </div>
      );
    }

    // Main Route Switch
    switch (route) {
      case AppRoute.DASHBOARD:
        return <Dashboard onNavigate={setRoute} />;
      case AppRoute.SALES:
        return <Sales />;
      case AppRoute.TRADE:
        return <Trade onNavigate={setRoute} />;
      case AppRoute.FINANCE:
        return <Finance onNavigate={setRoute} />;
      case AppRoute.COMPLIANCE:
        return <Compliance onNavigate={setRoute} />;
      case AppRoute.ASSISTANT:
        return <SmartAssistant />;
      case AppRoute.TOOLS:
        return <Tools onSelectTool={setActiveTool} onNavigate={setRoute} />;
      case AppRoute.DESIGN_DOC:
        return <SystemDesign />;
      default:
        return <Dashboard onNavigate={setRoute} />;
    }
  };

  const handleNavigate = (newRoute: AppRoute) => {
    setActiveTool(null);
    setRoute(newRoute);
  };

  return (
    <Layout currentRoute={route} onNavigate={handleNavigate}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Card, Button, Badge, Modal, Input, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { InventoryItem, AppRoute } from '../types';

interface TradeProps {
  onNavigate: (route: AppRoute) => void;
}

export const Trade: React.FC<TradeProps> = ({ onNavigate }) => {
  const [showStockModal, setShowStockModal] = useState(false);
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [cost, setCost] = useState('');
  const [price, setPrice] = useState('');
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });
  const [inventory, setInventory] = useState<InventoryItem[]>([]);

  // Load inventory
  useEffect(() => {
    setInventory(db.getInventory());
  }, []);

  const handleSaveStock = () => {
      if (!itemName || !quantity) return;

      const newItem: InventoryItem = {
          id: Date.now().toString(),
          name: itemName,
          quantity: parseInt(quantity),
          price: parseFloat(price) || 0,
          cost: parseFloat(cost) || 0,
          category: 'General',
          icon: '📦',
          lowStockThreshold: 5
      };

      db.addInventoryItem(newItem);
      setInventory(db.getInventory());

      setToast({ show: true, message: `Added ${quantity} x ${itemName}`, type: 'success' });
      setShowStockModal(false);

      // Reset
      setItemName('');
      setQuantity('');
      setCost('');
      setPrice('');

      setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
  };

  const lowStockItems = inventory.filter(i => i.quantity <= (i.lowStockThreshold || 0));

  return (
    <div className="space-y-6">
      <Toast show={toast.show} message={toast.message} type={toast.type} />

      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-neutral-900">Inventory</h2>
        <Button size="sm" variant="primary" onClick={() => setShowStockModal(true)}>
          + Add Stock
        </Button>
      </div>

      {/* 1. Low Stock Alerts (Real Data) */}
      {lowStockItems.length > 0 ? (
        <div className="bg-red-50 border border-red-100 rounded-2xl p-5">
            <div className="flex justify-between items-center mb-4">
                <h3 className="text-red-900 font-bold flex items-center">
                    <span className="text-xl mr-2">⚠️</span> Restock Needed
                </h3>
                <Badge variant="warning">{lowStockItems.length} Items</Badge>
            </div>
            <div className="space-y-3">
                {lowStockItems.map((item) => (
                    <div key={item.id} className="bg-white p-3 rounded-xl shadow-sm flex justify-between items-center">
                        <div>
                            <div className="font-bold text-neutral-900">{item.name}</div>
                            <div className="text-xs text-red-500 font-bold">{item.quantity} left</div>
                        </div>
                        <Button 
                          size="sm" 
                          variant="outline" 
                          className="text-xs h-8"
                          onClick={() => onNavigate(AppRoute.ASSISTANT)}
                        >
                          Order
                        </Button>
                    </div>
                ))}
            </div>
        </div>
      ) : (
        <div className="bg-green-50 border border-green-100 rounded-2xl p-5 flex items-center">
            <span className="text-2xl mr-3">✅</span>
            <div>
                <div className="font-bold text-green-900">All Stocked Up</div>
                <div className="text-xs text-green-700">Inventory levels are healthy.</div>
            </div>
        </div>
      )}

      {/* 2. My Suppliers */}
      <div>
          <h3 className="font-bold text-neutral-900 mb-3">My Suppliers</h3>
          <div className="grid grid-cols-2 gap-3">
              {[
                  { name: "Mama Dlamini", role: "Vegetables", color: "bg-green-100 text-green-700" },
                  { name: "Soweto Meat", role: "Meat/Chicken", color: "bg-red-100 text-red-700" },
                  { name: "Makro Cash", role: "Dry Goods", color: "bg-blue-100 text-blue-700" },
                  { name: "Coca-Cola", role: "Beverages", color: "bg-neutral-100 text-neutral-700" }
              ].map((s, i) => (
                  <button 
                    key={i} 
                    onClick={() => onNavigate(AppRoute.ASSISTANT)}
                    className="bg-white p-4 rounded-xl border border-neutral-200 shadow-sm text-left active:scale-95 transition-transform"
                  >
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold mb-3 ${s.color}`}>
                          {s.name[0]}
                      </div>
                      <div className="font-bold text-sm text-neutral-900 truncate">{s.name}</div>
                      <div className="text-xs text-neutral-500">{s.role}</div>
                  </button>
              ))}
          </div>
      </div>

      {/* 3. Inventory Overview */}
      <Card>
          <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-neutral-900">Stock Value</h3>
              <Badge variant="success">Healthy</Badge>
          </div>
          <div className="text-3xl font-extrabold text-neutral-900 mb-2">
             R {inventory.reduce((sum, item) => sum + (item.cost * item.quantity), 0).toLocaleString()}
          </div>
          <div className="w-full bg-neutral-100 h-2 rounded-full overflow-hidden">
              <div className="bg-green-500 h-full w-3/4"></div>
          </div>
          <p className="text-xs text-neutral-400 mt-2">{inventory.length} distinct products available</p>
      </Card>

      {/* STOCK MODAL */}
      <Modal isOpen={showStockModal} onClose={() => setShowStockModal(false)} title="Add Stock">
          <div className="space-y-4">
              <Input 
                  label="Item Name" 
                  placeholder="e.g. White Bread"
                  value={itemName}
                  onChange={(e) => setItemName(e.target.value)}
                  autoFocus
              />
              <div className="flex space-x-4">
                  <Input 
                      label="Quantity" 
                      type="number" 
                      placeholder="0"
                      value={quantity}
                      onChange={(e) => setQuantity(e.target.value)}
                  />
                  <Input 
                      label="Cost (Buy)" 
                      type="number" 
                      placeholder="0.00"
                      value={cost}
                      onChange={(e) => setCost(e.target.value)}
                  />
              </div>
              <Input 
                  label="Price (Sell)" 
                  type="number" 
                  placeholder="0.00"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
              />
              <Button fullWidth variant="primary" onClick={handleSaveStock} size="lg">
                  Save to Inventory
              </Button>
          </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
