             {/* Sync Status Indicator */}
             <div className="flex items-center text-[10px] font-bold text-neutral-400">
                {syncState === 'DONE' && <span className="text-green-500 mr-2">{t('synced')}</span>}
                {syncState === 'SYNCING' && <span className="text-blue-500 mr-2 animate-pulse">{t('syncing')}</span>}
             </div>

            <button 
                onClick={() => onNavigate(AppRoute.ASSISTANT)}
                className="w-9 h-9 bg-neutral-100 rounded-full flex items-center justify-center text-neutral-600 active:bg-neutral-200"
            >
              <span className="text-lg">🎙️</span>
            </button>
            <div className="w-9 h-9 bg-brand-900 rounded-full flex items-center justify-center text-white text-xs font-bold ring-2 ring-white shadow-sm">
              ST
            </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto pb-24 scroll-smooth">
        <div className="max-w-md mx-auto p-4 space-y-6">
          {children}
