      {/* Bottom Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t border-neutral-200 pb-safe z-30 shadow-[0_-4px_10px_rgba(0,0,0,0.03)]">
        <div className="max-w-md mx-auto flex justify-between px-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => onNavigate(item.id)}
              className={`flex flex-col items-center py-3 px-2 w-full transition-all active:scale-95 ${
                currentRoute === item.id 
                  ? 'text-brand-600' 
                  : 'text-neutral-400'
              }`}
            >
              <div className={`transition-transform duration-200 ${currentRoute === item.id ? '-translate-y-1' : ''}`}>
                {item.icon}
              </div>
              <span className={`text-[10px] font-bold mt-1 ${currentRoute === item.id ? 'opacity-100' : 'opacity-70'}`}>
                {item.label}
