          {/* Menu Item */}
          <button
              onClick={() => onNavigate(AppRoute.TOOLS)}
              className={`flex flex-col items-center py-3 px-2 w-full text-neutral-400 active:scale-95 ${currentRoute === AppRoute.TOOLS ? 'text-brand-600' : ''}`}
