             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
             <span className="text-[10px] font-bold mt-1">{t('menu')}</span>
          </button>
        </div>
      </nav>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Button, Modal, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { InventoryItem, SaleItem, Sale } from '../types';
import QRCode from 'qrcode';
import { useLanguage } from '../contexts/LanguageContext';

const RATE_NGN = 85; // 1 ZAR = ~85 NGN

export const Sales: React.FC = () => {
    const [amount, setAmount] = useState(0);
    const [cart, setCart] = useState<SaleItem[]>([]);
    const [inventory, setInventory] = useState<InventoryItem[]>([]);
    const [currency, setCurrency] = useState<'ZAR' | 'NGN'>('ZAR');

    // UI State
    const [showPaymentModal, setShowPaymentModal] = useState(false);
    const [showSuccessModal, setShowSuccessModal] = useState(false);
    const [lastSale, setLastSale] = useState<Sale | null>(null);
    const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });

    // QR Code State
    const [qrCodeUrl, setQrCodeUrl] = useState<string | null>(null);
    const [isGeneratingQR, setIsGeneratingQR] = useState(false);

    const { t } = useLanguage();

    // Load inventory from DB on mount
    useEffect(() => {
        setInventory(db.getInventory());
    }, []);

    // Helper: Format Price based on Currency
    const formatPrice = (val: number, showSymbol = true) => {
        if (currency === 'NGN') {
            const converted = val * RATE_NGN;
            return showSymbol ? `₦ ${converted.toLocaleString()}` : converted.toLocaleString();
        }
        return showSymbol ? `R ${val.toLocaleString()}` : val.toLocaleString();
    };

    const addToCart = (item: InventoryItem) => {
        setCart(prev => {
            const existing = prev.find(i => i.productId === item.id);
            if (existing) {
                return prev.map(i => i.productId === item.id ? { ...i, quantity: i.quantity + 1 } : i);
            }
            return [...prev, { productId: item.id, name: item.name, price: item.price, quantity: 1 }];
        });
        setAmount(prev => prev + item.price);
    };

    const handleClear = () => {
        setAmount(0);
        setCart([]);
        setQrCodeUrl(null);
    };

    const handleNewSale = () => {
        handleClear();
        setLastSale(null);
        setShowSuccessModal(false);
    };

    const initiatePayment = () => {
        if (amount === 0) return;
        setQrCodeUrl(null); // Reset QR state
        setShowPaymentModal(true);
    };

    const generatePaymentQR = async () => {
        setIsGeneratingQR(true);
        try {
            const transactionId = `txn_${Date.now()}`;
            const displayAmount = currency === 'NGN' ? amount * RATE_NGN : amount;

            const paymentData = {
                id: transactionId,
                amount: displayAmount,
                currency: currency,
                merchant: "IBOS Merchant",
                items: cart.map(i => ({ name: i.name, qty: i.quantity }))
            };

            const url = await QRCode.toDataURL(JSON.stringify(paymentData), {
                width: 256,
                margin: 2,
                color: {
                    dark: '#0B3C5D', // Primary brand color
                    light: '#FFFFFF'
                }
            });
            setQrCodeUrl(url);
        } catch (err) {
            console.error("QR Gen Error", err);
            setToast({ show: true, message: 'Could not generate QR code', type: 'error' });
        } finally {
            setIsGeneratingQR(false);
        }
    };

    const completeSale = (method: string) => {
        // 1. Create Sale Object
        const sale: Sale = {
            id: Date.now().toString(),
            items: cart,
            total: amount, // Store base ZAR amount
            currency, // Store currency used for transaction
            method,
            timestamp: Date.now(),
            synced: false
        };

        // 2. Save to Local DB (Instant)
        db.addSale(sale);

        // 3. Update UI Inventory (Optimistic)
        setInventory(prev => prev.map(invItem => {
            const cartItem = cart.find(c => c.productId === invItem.id);
            if (cartItem) {
                return { ...invItem, quantity: invItem.quantity - cartItem.quantity };
            }
            return invItem;
        }));

        // 4. Show Success
        setLastSale(sale);
        setShowPaymentModal(false);
        setShowSuccessModal(true);
        setQrCodeUrl(null);
    };

    const shareInvoiceWhatsApp = () => {
        if (!lastSale) return;

        const date = new Date(lastSale.timestamp).toLocaleDateString();
        const time = new Date(lastSale.timestamp).toLocaleTimeString();

        // Calculate display total based on the currency used during sale
        const isNgn = lastSale.currency === 'NGN';
        const rate = isNgn ? RATE_NGN : 1;
        const symbol = isNgn ? '₦' : 'R';
        const displayTotal = (lastSale.total * rate).toLocaleString();

        let message = `🧾 *INVOICE - IBOS Merchant*\n`;
        message += `📅 ${date} at ${time}\n`;
        message += `🆔 ${lastSale.id.slice(-6)}\n\n`;
        message += `*ITEMS:*\n`;
        lastSale.items.forEach(item => {
             const p = item.price * rate;
             message += `${item.quantity}x ${item.name} (${symbol}${p.toLocaleString()})\n`;
        });
        message += `\n*TOTAL: ${symbol} ${displayTotal}*\n`;
        message += `Paid via: ${lastSale.method}\n\n`;
        message += `Thank you for your business!`;

        const url = `https://wa.me/?text=${encodeURIComponent(message)}`;
        window.open(url, '_blank');
    };

    return (
        <div className="flex flex-col h-[calc(100vh-140px)]">
            <Toast show={toast.show} message={toast.message} type={toast.type} />

            {/* 1. TOTAL DISPLAY */}
            <div className="bg-white rounded-2xl p-6 shadow-soft-sm border border-neutral-200 mb-4 flex justify-between items-center relative">
                <div>
                    <div className="flex items-center space-x-2 mb-1">
                        <p className="text-xs font-bold text-neutral-400 uppercase tracking-wider">{t('currentSale')}</p>
                        <button 
                            onClick={() => setCurrency(prev => prev === 'ZAR' ? 'NGN' : 'ZAR')}
                            className="bg-neutral-100 px-2 py-0.5 rounded text-[10px] font-bold text-neutral-600 border border-neutral-200 active:bg-neutral-200 transition-colors"
                        >
                            {currency} ⇄
                        </button>
                    </div>
                    <div className="flex items-baseline">
                        <span className="text-2xl font-bold text-neutral-400 mr-2">{currency === 'NGN' ? '₦' : 'R'}</span>
                        <span className="text-5xl font-extrabold text-neutral-900 tracking-tighter">
                            {formatPrice(amount, false)}
                        </span>
                    </div>
                </div>
                {amount > 0 && (
                    <button 
                        onClick={handleClear}
                        className="absolute top-4 right-4 text-xs font-bold text-danger bg-red-50 px-3 py-1 rounded-full hover:bg-red-100"
                    >
                        {t('clear')}
                    </button>
                )}
            </div>

            {/* 2. PRODUCT GRID (From DB) */}
            <div className="flex-1 overflow-y-auto pb-4">
                <div className="grid grid-cols-2 gap-3">
                    {inventory.map((item) => (
                        <button 
                            key={item.id}
                            onClick={() => addToCart(item)}
                            className="bg-white p-4 rounded-2xl border border-neutral-200 shadow-soft-sm active:bg-neutral-50 active:scale-[0.98] transition-all flex items-center text-left h-24 relative overflow-hidden"
                        >
                            <span className="text-3xl mr-3">{item.icon || '📦'}</span>
                            <div className="flex-1 min-w-0">
                                <span className="text-sm font-bold text-neutral-900 block truncate">{item.name}</span>
                                <span className="text-xs font-bold text-accent-600">
                                    {formatPrice(item.price)}
                                </span>
                                {item.quantity <= (item.lowStockThreshold || 0) && (
                                    <span className="text-[10px] text-danger font-bold block">Low: {item.quantity}</span>
                                )}
                            </div>
                            {/* Quantity Badge in Cart */}
                            {cart.find(c => c.productId === item.id) && (
                                <div className="absolute top-2 right-2 bg-primary-900 text-white text-[10px] font-bold w-5 h-5 rounded-full flex items-center justify-center">
                                    {cart.find(c => c.productId === item.id)?.quantity}
                                </div>
                            )}
                        </button>
                    ))}
                    {/* Manual Entry */}
                    <button className="bg-neutral-50 p-4 rounded-2xl border-2 border-dashed border-neutral-200 flex items-center justify-center h-24 text-neutral-400">
                        <span className="text-sm font-bold">{t('manualKeypad')}</span>
                    </button>
                </div>
            </div>

            {/* 3. ACTION BAR */}
            <div className="mt-auto pt-2">
                <Button 
                    fullWidth 
                    variant="accent"
                    size="lg" 
                    onClick={initiatePayment} 
                    disabled={amount === 0}
                    className="text-lg shadow-glow"
                >
                    {t('charge')} {formatPrice(amount)}
                </Button>
            </div>

            {/* PAYMENT MODAL */}
            <Modal isOpen={showPaymentModal} onClose={() => setShowPaymentModal(false)} title="Select Payment Method">
                <div className="space-y-3">
                    {!qrCodeUrl ? (
                        <>
                            <button onClick={() => completeSale('Cash')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-accent-500 hover:bg-accent-50 transition-colors group">
                                <div className="w-12 h-12 rounded-full bg-green-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💵</div>
                                <div className="text-left">
                                    <div className="font-bold text-neutral-900 text-lg">Cash</div>
                                    <div className="text-xs text-neutral-500">Fastest</div>
                                </div>
                            </button>
                            <button onClick={() => completeSale('Card')} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-blue-500 hover:bg-blue-50 transition-colors group">
                                <div className="w-12 h-12 rounded-full bg-blue-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">💳</div>
                                <div className="text-left">
                                    <div className="font-bold text-neutral-900 text-lg">Card / Yoco</div>
                                    <div className="text-xs text-neutral-500">Record transaction</div>
                                </div>
                            </button>
                            <button onClick={generatePaymentQR} className="w-full flex items-center p-4 bg-white border border-neutral-200 rounded-2xl hover:border-neutral-900 hover:bg-neutral-50 transition-colors group">
                                <div className="w-12 h-12 rounded-full bg-neutral-100 flex items-center justify-center text-2xl mr-4 group-hover:bg-white">📱</div>
                                <div className="text-left">
                                    <div className="font-bold text-neutral-900 text-lg">Scan to Pay</div>
                                    <div className="text-xs text-neutral-500">Generate QR Code</div>
                                </div>
                            </button>
                        </>
                    ) : (
                        <div className="text-center animate-fade-in">
                            <div className="bg-white p-4 rounded-2xl border border-neutral-200 shadow-sm inline-block mb-4">
                                <img src={qrCodeUrl} alt="Payment QR" className="w-48 h-48" />
                            </div>
                            <p className="text-sm font-bold text-neutral-600 mb-4">Scan to pay {formatPrice(amount)}</p>
                            <div className="flex space-x-3">
                                <Button fullWidth variant="secondary" onClick={() => setQrCodeUrl(null)}>Back</Button>
                                <Button fullWidth variant="accent" onClick={() => completeSale('QR Payment')}>Confirm Payment</Button>
                            </div>
                        </div>
                    )}
                </div>
            </Modal>

            {/* SUCCESS / RECEIPT MODAL */}
            <Modal isOpen={showSuccessModal} onClose={handleNewSale} title={t('saleCompleted')}>
                <div className="text-center space-y-6">
                    <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto text-4xl shadow-sm animate-bounce-short">
                        ✅
                    </div>
                    <div>
                        <h2 className="text-2xl font-extrabold text-neutral-900">
                            {lastSale && (lastSale.currency === 'NGN' ? `₦ ${(lastSale.total * RATE_NGN).toLocaleString()}` : `R ${lastSale.total.toLocaleString()}`)}
                        </h2>
                        <p className="text-neutral-500 text-sm">Transaction Recorded Successfully</p>
                    </div>

                    <div className="space-y-3">
                        <button 
                            onClick={shareInvoiceWhatsApp}
                            className="w-full flex items-center justify-center p-4 bg-green-500 text-white font-bold rounded-2xl shadow-lg hover:bg-green-600 transition-colors"
                        >
                            <svg className="w-6 h-6 mr-2" fill="currentColor" viewBox="0 0 24 24"><path d="M.057 24l1.687-6.163c-1.041-1.804-1.588-3.849-1.587-5.946.003-6.556 5.338-11.891 11.893-11.891 3.181.001 6.167 1.24 8.413 3.488 2.245 2.248 3.481 5.236 3.48 8.414-.003 6.557-5.338 11.892-11.893 11.892-1.99-.001-3.951-.5-5.688-1.448l-6.305 1.654zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.434 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-5.452 0-9.887 4.434-9.889 9.884-.001 2.225.651 3.891 1.746 5.634l-.999 3.648 3.742-.981zm11.387-5.464c-.074-.124-.272-.198-.57-.347-.297-.149-1.758-.868-2.031-.967-.272-.099-.47-.149-.669.149-.198.297-.768.967-.941 1.165-.173.198-.347.223-.644.074-.297-.149-1.255-.462-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.297-.347.446-.521.151-.172.2-.296.3-.495.099-.198.05-.372-.025-.521-.075-.148-.669-1.611-.916-2.206-.242-.579-.487-.501-.669-.51l-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.095 3.2 5.076 4.487.709.306 1.263.489 1.694.626.712.226 1.36.194 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.695.248-1.29.173-1.414z"/></svg>
                            {t('shareWhatsapp')}
                        </button>
                        <Button fullWidth variant="secondary" onClick={handleNewSale}>
                            {t('newSale')}
                        </Button>
                    </div>
                </div>
            </Modal>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Card, Button, Badge, Modal, Input, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { InventoryItem, AppRoute } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface TradeProps {
  onNavigate: (route: AppRoute) => void;
}

export const Trade: React.FC<TradeProps> = ({ onNavigate }) => {
  const [showStockModal, setShowStockModal] = useState(false);
  const [itemName, setItemName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [cost, setCost] = useState('');
  const [price, setPrice] = useState('');
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const { t } = useLanguage();

  // Load inventory
  useEffect(() => {
    setInventory(db.getInventory());
  }, []);

  const handleSaveStock = () => {
      if (!itemName || !quantity) return;

      const newItem: InventoryItem = {
          id: Date.now().toString(),
          name: itemName,
          quantity: parseInt(quantity),
          price: parseFloat(price) || 0,
          cost: parseFloat(cost) || 0,
          category: 'General',
          icon: '📦',
          lowStockThreshold: 5
      };

      db.addInventoryItem(newItem);
      setInventory(db.getInventory());

      setToast({ show: true, message: `Added ${quantity} x ${itemName}`, type: 'success' });
      setShowStockModal(false);

      // Reset
      setItemName('');
      setQuantity('');
      setCost('');
      setPrice('');

      setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
  };

  const lowStockItems = inventory.filter(i => i.quantity <= (i.lowStockThreshold || 0));

  return (
    <div className="space-y-6">
      <Toast show={toast.show} message={toast.message} type={toast.type} />

      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-neutral-900">{t('inventory')}</h2>
        <Button size="sm" variant="primary" onClick={() => setShowStockModal(true)}>
          + {t('addStock')}
        </Button>
      </div>

      {/* 1. Low Stock Alerts (Real Data) */}
      {lowStockItems.length > 0 ? (
        <div className="bg-red-50 border border-red-100 rounded-2xl p-5">
            <div className="flex justify-between items-center mb-4">
                <h3 className="text-red-900 font-bold flex items-center">
                    <span className="text-xl mr-2">⚠️</span> {t('restockNeeded')}
                </h3>
                <Badge variant="warning">{lowStockItems.length} {t('items')}</Badge>
            </div>
            <div className="space-y-3">
                {lowStockItems.map((item) => (
                    <div key={item.id} className="bg-white p-3 rounded-xl shadow-sm flex justify-between items-center">
                        <div>
                            <div className="font-bold text-neutral-900">{item.name}</div>
                            <div className="text-xs text-red-500 font-bold">{item.quantity} left</div>
                        </div>
                        <Button 
                          size="sm" 
                          variant="outline" 
                          className="text-xs h-8"
                          onClick={() => onNavigate(AppRoute.ASSISTANT)}
                        >
                          {t('order')}
                        </Button>
                    </div>
                ))}
            </div>
        </div>
      ) : (
        <div className="bg-green-50 border border-green-100 rounded-2xl p-5 flex items-center">
            <span className="text-2xl mr-3">✅</span>
            <div>
                <div className="font-bold text-green-900">All Stocked Up</div>
                <div className="text-xs text-green-700">Inventory levels are healthy.</div>
            </div>
        </div>
      )}

      {/* 2. My Suppliers */}
      <div>
          <h3 className="font-bold text-neutral-900 mb-3">{t('mySuppliers')}</h3>
          <div className="grid grid-cols-2 gap-3">
              {[
                  { name: "Mama Dlamini", role: "Vegetables", color: "bg-green-100 text-green-700" },
                  { name: "Soweto Meat", role: "Meat/Chicken", color: "bg-red-100 text-red-700" },
                  { name: "Makro Cash", role: "Dry Goods", color: "bg-blue-100 text-blue-700" },
                  { name: "Coca-Cola", role: "Beverages", color: "bg-neutral-100 text-neutral-700" }
              ].map((s, i) => (
                  <button 
                    key={i} 
                    onClick={() => onNavigate(AppRoute.ASSISTANT)}
                    className="bg-white p-4 rounded-xl border border-neutral-200 shadow-sm text-left active:scale-95 transition-transform"
                  >
                      <div className={`w-10 h-10 rounded-full flex items-center justify-center font-bold mb-3 ${s.color}`}>
                          {s.name[0]}
                      </div>
                      <div className="font-bold text-sm text-neutral-900 truncate">{s.name}</div>
                      <div className="text-xs text-neutral-500">{s.role}</div>
                  </button>
              ))}
          </div>
      </div>

      {/* 3. Inventory Overview */}
      <Card>
          <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-neutral-900">{t('stockValue')}</h3>
              <Badge variant="success">{t('healthy')}</Badge>
          </div>
          <div className="text-3xl font-extrabold text-neutral-900 mb-2">
             R {inventory.reduce((sum, item) => sum + (item.cost * item.quantity), 0).toLocaleString()}
          </div>
          <div className="w-full bg-neutral-100 h-2 rounded-full overflow-hidden">
              <div className="bg-green-500 h-full w-3/4"></div>
          </div>
          <p className="text-xs text-neutral-400 mt-2">{inventory.length} distinct products available</p>
      </Card>

      {/* STOCK MODAL */}
      <Modal isOpen={showStockModal} onClose={() => setShowStockModal(false)} title={t('addStock')}>
          <div className="space-y-4">
              <Input 
                  label="Item Name" 
                  placeholder="e.g. White Bread"
                  value={itemName}
                  onChange={(e) => setItemName(e.target.value)}
                  autoFocus
              />
              <div className="flex space-x-4">
                  <Input 
                      label="Quantity" 
                      type="number" 
                      placeholder="0"
                      value={quantity}
                      onChange={(e) => setQuantity(e.target.value)}
                  />
                  <Input 
                      label="Cost (Buy)" 
                      type="number" 
                      placeholder="0.00"
                      value={cost}
                      onChange={(e) => setCost(e.target.value)}
                  />
              </div>
              <Input 
                  label="Price (Sell)" 
                  type="number" 
                  placeholder="0.00"
                  value={price}
                  onChange={(e) => setPrice(e.target.value)}
              />
              <Button fullWidth variant="primary" onClick={handleSaveStock} size="lg">
                  Save to Inventory
              </Button>
          </div>
      </Modal>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Card, Button, Badge, Modal, Input, Toast } from '../components/DesignSystem';
import { db } from '../services/storage';
import { AppRoute } from '../types';
import { useLanguage } from '../contexts/LanguageContext';

interface FinanceProps {
  onNavigate: (route: AppRoute) => void;
}

export const Finance: React.FC<FinanceProps> = ({ onNavigate }) => {
  const [showExpenseModal, setShowExpenseModal] = useState(false);
  const [expenseAmount, setExpenseAmount] = useState('');
  const [expenseCategory, setExpenseCategory] = useState('');
  const [toast, setToast] = useState({ show: false, message: '', type: 'success' as 'success' | 'error' | 'info' });
  const [financials, setFinancials] = useState({ totalRevenue: 0, totalExpenses: 0, profit: 0 });
  const { t } = useLanguage();

  // Load financials
  useEffect(() => {
    setFinancials(db.getFinancialSummary());
  }, [showExpenseModal]); // Reload when expense added

  const handleSaveExpense = () => {
    if (!expenseAmount) return;

    db.addExpense({
        id: Date.now().toString(),
        amount: parseFloat(expenseAmount),
        category: expenseCategory || 'General',
        timestamp: Date.now(),
        synced: false
    });

    setToast({ show: true, message: `Saved expense: R${expenseAmount}`, type: 'success' });
    setShowExpenseModal(false);
    setExpenseAmount('');
    setExpenseCategory('');
    setTimeout(() => setToast(prev => ({ ...prev, show: false })), 3000);
  };

  const showFeatureToast = () => {
    setToast({ show: true, message: "Banking integration coming soon!", type: 'info' });
    setTimeout(() => setToast(prev => ({ ...prev, show: false })), 2000);
  };

  return (
    <div className="space-y-6">
      <Toast show={toast.show} message={toast.message} type={toast.type} />

      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold text-neutral-900">{t('moneyControl')}</h2>
        <Button size="sm" variant="danger" onClick={() => setShowExpenseModal(true)}>
          + {t('logExpense')}
        </Button>
      </div>

      {/* 1. Profit & Loss (Real Data) */}
      <div className="grid grid-cols-2 gap-4">
          <div className="bg-green-50 border border-green-100 p-4 rounded-2xl">
              <div className="text-xs font-bold text-green-700 uppercase tracking-wider mb-1">In ({t('sale')})</div>
              <div className="text-xl font-extrabold text-green-800">R {financials.totalRevenue.toLocaleString()}</div>
              <div className="text-[10px] text-green-600">Total</div>
          </div>
          <div className="bg-red-50 border border-red-100 p-4 rounded-2xl">
              <div className="text-xs font-bold text-red-700 uppercase tracking-wider mb-1">Out (Cost)</div>
              <div className="text-xl font-extrabold text-red-800">R {financials.totalExpenses.toLocaleString()}</div>
              <div className="text-[10px] text-red-600">Total</div>
          </div>
      </div>

      <Card className="bg-neutral-900 text-white border-none">
          <div className="flex justify-between items-start">
            <div>
                <p className="text-xs font-bold text-neutral-400 uppercase">{t('profit')}</p>
                <h3 className="text-3xl font-bold mt-1">R {financials.profit.toLocaleString()}</h3>
            </div>
            <div className="bg-white/10 p-2 rounded-lg text-2xl">
                {financials.profit >= 0 ? '😀' : '📉'}
            </div>
          </div>
          <p className="text-xs text-neutral-500 mt-2">
            {financials.profit >= 0 ? "You are making money!" : "Expenses are higher than sales."}
          </p>
      </Card>

      {/* 2. Savings Wallet */}
      <div className="bg-white border border-neutral-200 rounded-2xl p-5 shadow-sm">
          <div className="flex justify-between items-center mb-4">
              <h3 className="font-bold text-neutral-900">{t('savingsWallet')}</h3>
              <Badge variant="info">Safe Lock</Badge>
          </div>
          <div className="flex items-center space-x-4 mb-4">
              <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 text-xl">🐷</div>
              <div>
                  <div className="font-bold text-lg">R 450.00</div>
                  <div className="text-xs text-neutral-500">{t('goal')}: R 2,000 for School Fees</div>
              </div>
          </div>
          <div className="grid grid-cols-2 gap-3">
              <Button size="sm" variant="outline" onClick={showFeatureToast}>{t('withdraw')}</Button>
              <Button size="sm" variant="primary" onClick={showFeatureToast}>{t('add')} R50</Button>
          </div>
      </div>

      {/* 3. Credit Score */}
      <Card className="relative overflow-hidden">
         <div className="relative z-10">
            <div className="flex justify-between mb-4">
                <h3 className="font-bold text-neutral-900">{t('loanEligibility')}</h3>
                <span className="text-xs font-bold bg-teal-100 text-teal-700 px-2 py-1 rounded">Good</span>
            </div>
            <p className="text-sm text-neutral-600 mb-4">Based on your sales, you qualify for a quick loan.</p>

            <div className="bg-neutral-50 rounded-xl p-3 border border-neutral-100 flex justify-between items-center">
                <div>
                    <div className="text-xs text-neutral-400 font-bold uppercase">Available</div>
                    <div className="text-xl font-bold text-neutral-900">R 5,000</div>
                </div>
                <Button size="sm" onClick={() => onNavigate(AppRoute.ASSISTANT)}>{t('apply')}</Button>
            </div>
         </div>
      </Card>

       {/* EXPENSE MODAL */}
       <Modal isOpen={showExpenseModal} onClose={() => setShowExpenseModal(false)} title={t('logExpense')}>
         <div className="space-y-4">
            <Input 
                label="Amount (R)" 
                type="number" 
                placeholder="0.00" 
                value={expenseAmount}
                onChange={(e) => setExpenseAmount(e.target.value)}
                autoFocus
            />
            <div>
                 <label className="block text-xs font-bold text-neutral-500 mb-2 ml-1 uppercase tracking-wide">Category</label>
                 <div className="grid grid-cols-2 gap-2">
                    {['Stock', 'Transport', 'Rent', 'Wages'].map(cat => (
                        <button 
                            key={cat}
                            onClick={() => setExpenseCategory(cat)}
                            className={`p-3 rounded-xl border text-sm font-bold transition-all ${expenseCategory === cat ? 'bg-danger text-white border-danger shadow-md' : 'bg-white text-neutral-500 border-neutral-200 hover:bg-neutral-50'}`}
                        >
                            {cat}
                        </button>
                    ))}
                </div>
            </div>
            <Input 
                label="Note (Optional)" 
                placeholder="Details..." 
                value={expenseCategory && !['Stock', 'Transport', 'Rent', 'Wages'].includes(expenseCategory) ? expenseCategory : ''}
                onChange={(e) => setExpenseCategory(e.target.value)}
            />
            <Button fullWidth variant="danger" onClick={handleSaveExpense} size="lg">
                Save Expense
            </Button>
         </div>
      </Modal>
    </div>
  );
};

